insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekly-energy-budget-planner', 'Weekly Energy Budget Planner', 'worksheet'::resource_kind, 'Maps where a client''s energy goes across a typical week against where they want it to go.', 'Make energy, not just time, a visible resource the client can budget on purpose.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client list the week''s regular commitments and rate each one as energy-giving or energy-costing, then compare the total against how the week actually felt. Most clients are surprised by how lopsided the ledger is. Use it to find one costly commitment worth trimming and one giving one worth protecting.', '[{"id": "f0", "type": "textarea", "label": "Commitments in a typical week"}, {"id": "f1", "type": "textarea", "label": "Which ones give energy, which cost it"}, {"id": "f2", "type": "textarea", "label": "Where the week felt most drained"}, {"id": "f3", "type": "textarea", "label": "One costly commitment I could trim"}, {"id": "f4", "type": "textarea", "label": "One energy-giving thing I want to protect"}, {"id": "f5", "type": "textarea", "label": "What a better-balanced week would look like"}]'::jsonb, array['self-monitoring', 'burnout', 'routines']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('decision-fork-worksheet', 'Decision Fork Worksheet', 'worksheet'::resource_kind, 'Lays out a stuck decision as a fork with the real costs and pulls of each path.', 'Turn circular worry about a decision into a side-by-side comparison the client can act on.', array['Adults']::text[], '20 minutes', 'Useful when a client has been turning the same decision over for weeks without moving. Naming both paths concretely, including what staying the same actually costs, often breaks the freeze better than more pros-and-cons debate. Ask what information, if any, is still missing versus what is just discomfort with choosing.', '[{"id": "f0", "type": "textarea", "label": "The decision I keep circling"}, {"id": "f1", "type": "textarea", "label": "Path A, plainly stated"}, {"id": "f2", "type": "textarea", "label": "Path B, plainly stated"}, {"id": "f3", "type": "textarea", "label": "What each path costs me"}, {"id": "f4", "type": "textarea", "label": "What each path gives me"}, {"id": "f5", "type": "textarea", "label": "What I actually still need to know before choosing"}]'::jsonb, array['decision-making', 'rumination']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('self-talk-audit', 'Self-Talk Audit', 'worksheet'::resource_kind, 'Catalogs the client''s habitual inner commentary across a few situations to see its tone.', 'Make an automatic internal voice something the client can hear and evaluate.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to jot the exact words their mind used in a handful of recent moments, not a summary of the gist. Reading them back aloud in session is often the most useful part, since clients rarely notice the tone until they hear it said to someone else. Compare the voice to how the client would actually talk to a friend in the same spot.', '[{"id": "f0", "type": "textarea", "label": "A recent moment and what my mind said, word for word"}, {"id": "f1", "type": "textarea", "label": "Another moment, same instructions"}, {"id": "f2", "type": "textarea", "label": "A third moment"}, {"id": "f3", "type": "textarea", "label": "The tone across all three, in one word"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend in the same spot"}, {"id": "f5", "type": "textarea", "label": "One phrase I want to try instead"}]'::jsonb, array['self-talk', 'core beliefs']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('identity-roles-inventory', 'Identity Roles Inventory', 'worksheet'::resource_kind, 'Lists the roles a client currently carries and how much weight each one holds.', 'Locate which roles are overloaded and which parts of identity have gone quiet.', array['Adults']::text[], '25 minutes', 'Have the client list every role currently in play, worker, parent, partner, sibling, friend, and rate how much of the week each one takes versus how much it feels chosen. Roles that took over without being chosen are worth a closer look, as are ones the client used to hold and has let go of. This works well alongside a values conversation.', '[{"id": "f0", "type": "textarea", "label": "Every role I currently carry"}, {"id": "f1", "type": "textarea", "label": "How much of my week each takes"}, {"id": "f2", "type": "textarea", "label": "Which ones feel chosen versus just happening"}, {"id": "f3", "type": "textarea", "label": "A role that has quietly disappeared"}, {"id": "f4", "type": "textarea", "label": "A role I would add if I could"}, {"id": "f5", "type": "textarea", "label": "One small shift I could make this month"}]'::jsonb, array['values', 'burnout', 'self-monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('new-habit-trial-sheet', 'New Habit Trial Sheet', 'worksheet'::resource_kind, 'Structures a two-week trial of one small habit with a plain way to track it.', 'Test a habit change on a short timeline before the client commits to it long term.', array['Adults', 'Teens']::text[], 'Two weeks', 'Pick one small, specific habit and a daily yes-or-no mark rather than a graded rating, since graded scales invite second-guessing. Review at the two-week mark and treat missed days as data about the plan, not about the client''s willpower. A habit that needed constant force to keep up usually needs redesigning, not more discipline.', '[{"id": "f0", "type": "textarea", "label": "The habit I am trialing"}, {"id": "f1", "type": "textarea", "label": "Why this one, right now"}, {"id": "f2", "type": "textarea", "label": "Day-by-day yes or no tally"}, {"id": "f3", "type": "textarea", "label": "What made it easier on the good days"}, {"id": "f4", "type": "textarea", "label": "What got in the way on the missed days"}, {"id": "f5", "type": "textarea", "label": "Keep it, change it, or drop it"}]'::jsonb, array['habits', 'behavioral', 'self-monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('prediction-vs-outcome-log', 'Prediction vs Outcome Log', 'cbt'::resource_kind, 'Tracks what a client predicts will happen against what actually happens across a week.', 'Build a running record that challenges an overconfident worry pattern with the client''s own data.', array['Adults', 'Teens']::text[], 'One week', 'Before a feared situation, have the client write the specific prediction and how certain they feel, then fill in the actual outcome afterward without editing the earlier entry. The gap between predicted and actual certainty across several entries is usually more persuasive than any single conversation. Keep the log going past the point it seems to be working.', '[{"id": "f0", "type": "textarea", "label": "Situation coming up"}, {"id": "f1", "type": "textarea", "label": "My exact prediction"}, {"id": "f2", "type": "textarea", "label": "How certain I am (0 to 100)"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "How the outcome compared"}, {"id": "f5", "type": "textarea", "label": "What I notice across this week''s entries"}]'::jsonb, array['core CBT', 'thinking traps', 'monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('core-belief-origins-timeline', 'Core Belief Origins Timeline', 'cbt'::resource_kind, 'Traces a core belief back through the client''s history to where it first took hold.', 'Give a rigid belief a beginning, middle and present so it reads as learned rather than as fact.', array['Adults']::text[], '30 minutes', 'Start from the belief itself, then work backward through the client''s life for the earliest memory it fits, the moments it got reinforced, and any evidence along the way that never got counted. Clients often locate the belief''s origin in a much younger version of themselves than they expected. Close by asking what that younger self needed to hear instead.', '[{"id": "f0", "type": "textarea", "label": "The belief, in the client''s own words"}, {"id": "f1", "type": "textarea", "label": "Earliest memory it connects to"}, {"id": "f2", "type": "textarea", "label": "Moments over the years that reinforced it"}, {"id": "f3", "type": "textarea", "label": "Evidence that contradicted it but got overlooked"}, {"id": "f4", "type": "textarea", "label": "What the younger self needed to hear"}, {"id": "f5", "type": "textarea", "label": "A more accurate belief to test out"}]'::jsonb, array['core beliefs', 'core CBT', 'formulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('hot-thought-bullseye', 'Hot Thought Bullseye', 'cbt'::resource_kind, 'Narrows a tangle of thoughts in a distressing moment down to the single hottest one.', 'Find the one thought driving most of the distress so the rest of the work can target it.', array['Adults', 'Teens']::text[], '15 minutes', 'When a client brings a messy, multi-thought moment, list every thought that showed up and have them rate each for how much distress it carries on its own. The bullseye center is whichever thought scores highest; that is the one worth a full thought record, not the others. This keeps sessions from spreading thin across low-value thoughts.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "Every thought that showed up"}, {"id": "f2", "type": "textarea", "label": "Distress rating for each thought"}, {"id": "f3", "type": "textarea", "label": "The hottest thought"}, {"id": "f4", "type": "textarea", "label": "What makes that one the hottest"}, {"id": "f5", "type": "textarea", "label": "The angle to work on first"}]'::jsonb, array['core CBT', 'thinking traps']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('rule-for-living-rewrite', 'Rule for Living Rewrite', 'cbt'::resource_kind, 'Surfaces an unspoken personal rule and drafts a more workable version of it.', 'Turn a rigid if-then rule the client lives by into something flexible enough to actually follow.', array['Adults']::text[], '25 minutes', 'Many clients operate on an unstated rule, such as needing to be useful to deserve rest, that drives behavior more than any belief they would state out loud. Help the client word the rule plainly, list what it costs to keep it, and draft a looser version that still respects what the original rule was trying to protect. Test the new rule for a week before treating it as settled.', '[{"id": "f0", "type": "textarea", "label": "The rule, put into words"}, {"id": "f1", "type": "textarea", "label": "Where it likely came from"}, {"id": "f2", "type": "textarea", "label": "What it costs to follow it"}, {"id": "f3", "type": "textarea", "label": "What it was trying to protect"}, {"id": "f4", "type": "textarea", "label": "A more workable version of the rule"}, {"id": "f5", "type": "textarea", "label": "How I will test the new version this week"}]'::jsonb, array['core beliefs', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('alternative-explanations-wheel', 'Alternative Explanations Wheel', 'cbt'::resource_kind, 'Generates several possible explanations for an ambiguous situation before settling on one.', 'Loosen a client''s default explanation by putting real alternatives next to it.', array['Adults', 'Teens']::text[], '15 minutes', 'Ambiguous situations, an unanswered text, a flat tone from a coworker, tend to get filled in with the client''s most familiar and usually harshest explanation by default. Have the client generate at least four different explanations before rating how likely each one actually is. The point is not to force optimism but to break the habit of stopping at the first, worst guess.', '[{"id": "f0", "type": "textarea", "label": "The ambiguous situation"}, {"id": "f1", "type": "textarea", "label": "My first, automatic explanation"}, {"id": "f2", "type": "textarea", "label": "Three other possible explanations"}, {"id": "f3", "type": "textarea", "label": "How likely each one actually is"}, {"id": "f4", "type": "textarea", "label": "What evidence would tell them apart"}, {"id": "f5", "type": "textarea", "label": "What I will do while I do not know"}]'::jsonb, array['core CBT', 'thinking traps']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('tug-of-war-with-the-monster-metaphor', 'Tug-of-War With the Monster Metaphor', 'act'::resource_kind, 'Walks through the classic tug-of-war image to loosen a client''s grip on an ongoing struggle.', 'Let go of unproductive effort by noticing the rope, not the monster, is the thing to drop.', array['Adults', 'Teens']::text[], '15 minutes', 'Describe the scene together: a monster on one end of a rope, the client straining on the other, the harder they pull the harder it pulls back. Ask what happens to the client''s life while both hands are on the rope. The move is not winning the tug-of-war but noticing the rope can simply be set down, which is a strange and sometimes uncomfortable idea worth sitting with.', '[{"id": "f0", "type": "textarea", "label": "The struggle this fits for me"}, {"id": "f1", "type": "textarea", "label": "What pulling harder has actually gotten me"}, {"id": "f2", "type": "textarea", "label": "What I have missed while both hands were on the rope"}, {"id": "f3", "type": "textarea", "label": "What it would mean to set the rope down"}, {"id": "f4", "type": "textarea", "label": "What I am afraid would happen if I did"}]'::jsonb, array['core ACT', 'acceptance', 'willingness']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('silly-voice-thought-replay', 'Silly Voice Thought Replay', 'act'::resource_kind, 'Has the client repeat a sticky thought aloud in a series of silly voices.', 'Loosen the grip of a literal, believable thought through simple, repeated defusion practice.', array['Adults', 'Teens']::text[], '10 minutes', 'Pick one recurring thought and have the client say it in their normal voice, then a cartoon voice, then singing it, then very slowly. Most clients start laughing partway through, which is the point: the words have not changed but the relationship to them has loosened. Note how differently the thought lands by the end compared to the first read.', '[{"id": "f0", "type": "textarea", "label": "The sticky thought, written plainly"}, {"id": "f1", "type": "textarea", "label": "How it felt to say it normally"}, {"id": "f2", "type": "textarea", "label": "How it felt in a silly voice"}, {"id": "f3", "type": "textarea", "label": "How it felt sung or slowed down"}, {"id": "f4", "type": "textarea", "label": "How much I believe it now, compared to before"}]'::jsonb, array['core ACT', 'defusion']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('values-in-ten-years-letter', 'Values in Ten Years Letter', 'act'::resource_kind, 'Has the client write from ten years ahead, describing a life shaped by their values.', 'Use distance in time to clarify which values matter enough to build a life around.', array['Adults']::text[], '30 minutes', 'Ask the client to write as their future self looking back, describing what mattered enough to keep showing up for even on hard days. Steer away from achievements and toward the qualities the client wants to have brought to their days, since that framing tracks values rather than outcomes. Bring the letter back into the present by asking what one line points to doing this month.', '[{"id": "f0", "type": "textarea", "label": "Opening: where I am, ten years from now"}, {"id": "f1", "type": "textarea", "label": "What I kept showing up for"}, {"id": "f2", "type": "textarea", "label": "How I want to have treated people along the way"}, {"id": "f3", "type": "textarea", "label": "A hard stretch I got through and how"}, {"id": "f4", "type": "textarea", "label": "One line from this letter I want to act on this month"}]'::jsonb, array['values', 'core ACT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('acceptance-ladder-for-difficult-feelings', 'Acceptance Ladder for Difficult Feelings', 'act'::resource_kind, 'Ranks a set of hard feelings from most to least willing to make room for, and works up the rungs.', 'Build willingness gradually rather than asking for full acceptance all at once.', array['Adults', 'Teens']::text[], '20 minutes', 'List several feelings the client tends to fight rather than allow, from mildly uncomfortable to the ones that trigger the most avoidance, and order them into a ladder. Start practice on the lowest rung: naming the feeling, making room for it in the body, and continuing with the activity at hand anyway. Move up only once a rung feels workable, not once it feels comfortable.', '[{"id": "f0", "type": "textarea", "label": "Feelings I tend to fight, listed low to high"}, {"id": "f1", "type": "textarea", "label": "The lowest rung I will start on"}, {"id": "f2", "type": "textarea", "label": "What making room for it looks like in my body"}, {"id": "f3", "type": "textarea", "label": "What I can still do while feeling it"}, {"id": "f4", "type": "textarea", "label": "Signs I am ready to move up a rung"}]'::jsonb, array['core ACT', 'willingness', 'acceptance']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('sky-and-weather-self-metaphor', 'Sky and Weather Self-Metaphor', 'act'::resource_kind, 'Uses the image of sky and weather to separate a client''s sense of self from passing moods.', 'Give the client language for being the container for a feeling rather than the feeling itself.', array['Adults', 'Teens']::text[], '15 minutes', 'Introduce the image simply: the client is the sky, thoughts and feelings are the weather passing through it, and no storm, however severe, changes what the sky fundamentally is. Ask the client to describe today''s weather without describing the sky as changed by it. This exercise pairs well with a values or committed action conversation once the distinction has landed.', '[{"id": "f0", "type": "textarea", "label": "Today''s weather, in my own words"}, {"id": "f1", "type": "textarea", "label": "How intense this weather feels, out of ten"}, {"id": "f2", "type": "textarea", "label": "What stays the same about the sky underneath it"}, {"id": "f3", "type": "textarea", "label": "A past storm that has already passed through"}, {"id": "f4", "type": "textarea", "label": "What the sky can still do while the weather happens"}]'::jsonb, array['core ACT', 'observing self']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('emotion-vulnerability-factors-log', 'Emotion Vulnerability Factors Log', 'dbt'::resource_kind, 'Tracks the physical and situational factors that make emotions harder to manage on a given day.', 'Spot the vulnerability factors, not just the trigger, behind an emotional spike.', array['Adults', 'Teens']::text[], 'One week', 'Each evening, have the client rate sleep, eating, physical illness and substance use for the day alongside the day''s emotional intensity. Patterns usually surface within a week: a short night or a skipped meal often explains a reaction better than the event that seemed to trigger it. Use the log to plan which vulnerability factor to shore up first.', '[{"id": "f0", "type": "textarea", "label": "Sleep last night"}, {"id": "f1", "type": "textarea", "label": "Meals today"}, {"id": "f2", "type": "textarea", "label": "Physical illness or pain today"}, {"id": "f3", "type": "textarea", "label": "Substance use today, if any"}, {"id": "f4", "type": "textarea", "label": "Most intense emotion today and its cause"}, {"id": "f5", "type": "textarea", "label": "The vulnerability factor most worth addressing"}]'::jsonb, array['distress tolerance', 'self-monitoring', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('middle-path-both-and-worksheet', 'Middle Path Both/And Worksheet', 'dbt'::resource_kind, 'Practices holding two seemingly opposite truths about a situation at the same time.', 'Replace either-or thinking with a both-and statement that fits the situation better.', array['Adults', 'Teens']::text[], '20 minutes', 'Give the client an either-or statement they have been stuck on, such as being a good parent or needing space, and have them draft a both-and version that holds both truths without canceling either one. This is dialectical thinking in practice: two things that feel contradictory can both be true. Practice on a few different situations until the both-and move starts to feel available in the moment, not just on paper.', '[{"id": "f0", "type": "textarea", "label": "The either-or statement I keep landing on"}, {"id": "f1", "type": "textarea", "label": "What is true about the first side"}, {"id": "f2", "type": "textarea", "label": "What is true about the second side"}, {"id": "f3", "type": "textarea", "label": "A both-and version that holds both"}, {"id": "f4", "type": "textarea", "label": "A situation this week where I could try the both-and version"}]'::jsonb, array['dialectics', 'core beliefs']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-stance-practice', 'Nonjudgmental Stance Practice', 'dbt'::resource_kind, 'Practices describing a recent moment in purely factual terms, with the judgments removed.', 'Build the mindfulness skill of separating what happened from the verdict placed on it.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client describe a recent moment twice: once exactly as they first told it, judgments included, and once again with every good, bad, should and shouldn''t stripped out, leaving only what a camera would have recorded. Most clients are surprised how much shorter and calmer the second version reads. This skill takes repeated practice before it shows up automatically under stress.', '[{"id": "f0", "type": "textarea", "label": "The moment, told as I first would"}, {"id": "f1", "type": "textarea", "label": "Judging words I used (good, bad, should, terrible, etc.)"}, {"id": "f2", "type": "textarea", "label": "The same moment with those words removed"}, {"id": "f3", "type": "textarea", "label": "What is left when only the facts remain"}, {"id": "f4", "type": "textarea", "label": "How the two versions felt different to say"}]'::jsonb, array['mindfulness', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('interpersonal-effectiveness-priorities-sheet', 'Interpersonal Effectiveness Priorities Sheet', 'dbt'::resource_kind, 'Ranks objectives, the relationship and self-respect before a hard conversation to decide what to prioritize.', 'Choose in advance what matters most in a conversation so the DEAR MAN script actually fits the goal.', array['Adults', 'Teens']::text[], '15 minutes', 'Before a difficult conversation, have the client rank getting the objective met, keeping the relationship intact and keeping self-respect intact, since a script that tries to maximize all three at once often backfires. Naming the real priority in advance changes tone, timing and how firmly to push. Revisit after the conversation to see whether the priority held.', '[{"id": "f0", "type": "textarea", "label": "The conversation coming up"}, {"id": "f1", "type": "textarea", "label": "How much the objective matters, out of ten"}, {"id": "f2", "type": "textarea", "label": "How much the relationship matters, out of ten"}, {"id": "f3", "type": "textarea", "label": "How much self-respect matters, out of ten"}, {"id": "f4", "type": "textarea", "label": "My actual priority for this one"}, {"id": "f5", "type": "textarea", "label": "How that priority should change my approach"}]'::jsonb, array['DEAR MAN', 'communication']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('building-mastery-weekly-plan', 'Building Mastery Weekly Plan', 'dbt'::resource_kind, 'Schedules one activity a day the client is likely to do well, to build a sense of competence.', 'Counter a low mood or low confidence spiral with small, engineered wins.', array['Adults', 'Teens']::text[], 'One week', 'Have the client plan one activity each day that is slightly challenging but achievable, not a chore and not a stretch goal, and note afterward how it actually went. The aim is a felt sense of competence accumulating across the week, which tends to lift mood more reliably than rest alone. Keep the bar low enough on hard days that the plan does not become one more thing to fail at.', '[{"id": "f0", "type": "textarea", "label": "Monday''s planned activity and how it went"}, {"id": "f1", "type": "textarea", "label": "Tuesday''s"}, {"id": "f2", "type": "textarea", "label": "Wednesday''s"}, {"id": "f3", "type": "textarea", "label": "Thursday''s"}, {"id": "f4", "type": "textarea", "label": "Friday''s"}, {"id": "f5", "type": "textarea", "label": "What I noticed about my confidence across the week"}]'::jsonb, array['skills', 'behavioral activation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('money-talk-agenda-for-couples', 'Money Talk Agenda for Couples', 'couples'::resource_kind, 'Structures a recurring money conversation so it stays practical instead of turning into a fight.', 'Get both partners talking about money on a schedule instead of only in the middle of a crisis.', array['Couples']::text[], '30 minutes', 'Money conversations that only happen during a crisis tend to go badly, so this sets a standing time and a fixed order: numbers first, feelings second, decisions last. Each partner gets uninterrupted time on the feelings section before any decision gets discussed. Keep the first few sessions short and low-stakes to build the habit before tackling a bigger decision.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the numbers as I see them"}, {"id": "f1", "type": "textarea", "label": "Partner B: the numbers as I see them"}, {"id": "f2", "type": "textarea", "label": "Partner A: how money feels to talk about"}, {"id": "f3", "type": "textarea", "label": "Partner B: how money feels to talk about"}, {"id": "f4", "type": "textarea", "label": "One decision we need to make"}, {"id": "f5", "type": "textarea", "label": "What we agreed"}]'::jsonb, array['communication', 'conflict']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('stonewalling-time-out-plan', 'Stonewalling Time-Out Plan', 'couples'::resource_kind, 'Builds an agreed way to pause a conversation before either partner shuts down, with a return plan.', 'Replace an unplanned shutdown with a structured pause that both partners trust will lead back to the conversation.', array['Couples']::text[], '20 minutes', 'Shutting down mid-conflict often feels necessary to the partner doing it and abandoning to the other, so the fix is agreeing on the pause in advance rather than in the moment. Set a physical signal, a minimum and maximum break length, and what each partner will do to calm down during it. The plan only works if the return to the conversation is guaranteed, not optional.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what shutting down looks like for me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what it looks like for me"}, {"id": "f2", "type": "textarea", "label": "The signal we will use to call a pause"}, {"id": "f3", "type": "textarea", "label": "What each of us will do during the break"}, {"id": "f4", "type": "textarea", "label": "How long the break will be"}, {"id": "f5", "type": "textarea", "label": "How we will restart the conversation"}]'::jsonb, array['conflict', 'flooding', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-appreciation-interview', 'Partner Appreciation Interview', 'couples'::resource_kind, 'Has each partner interview the other about a specific quality they admire, in detail.', 'Slow down a vague compliment into a specific, well-observed appreciation.', array['Couples']::text[], '20 minutes', 'Rather than trading general compliments, have each partner pick one quality in the other and ask follow-up questions until the appreciation gets specific: a moment it showed up, why it matters, what it makes possible. Being interviewed about a strength lands differently than being told about it in passing. Switch roles so both partners get to ask and be asked.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the quality I admire in you"}, {"id": "f1", "type": "textarea", "label": "Partner A: a specific moment it showed up"}, {"id": "f2", "type": "textarea", "label": "Partner B: the quality I admire in you"}, {"id": "f3", "type": "textarea", "label": "Partner B: a specific moment it showed up"}, {"id": "f4", "type": "textarea", "label": "What it was like to be interviewed this way"}]'::jsonb, array['Gottman', 'fondness and admiration']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('in-law-and-extended-family-boundaries-sheet', 'In-Law and Extended Family Boundaries Sheet', 'couples'::resource_kind, 'Maps where extended family involvement feels welcome versus intrusive for each partner.', 'Get a couple''s boundaries with extended family stated out loud instead of assumed.', array['Couples']::text[], '25 minutes', 'Extended family friction is often less about the family and more about the couple never having agreed on the line together, leaving one partner to defend a boundary the other never signed onto. Have each partner list where involvement feels welcome and where it does not, then draft one shared position to present as a united front. Revisit before a holiday or major event.', '[{"id": "f0", "type": "textarea", "label": "Partner A: where family involvement feels welcome"}, {"id": "f1", "type": "textarea", "label": "Partner A: where it feels intrusive"}, {"id": "f2", "type": "textarea", "label": "Partner B: where family involvement feels welcome"}, {"id": "f3", "type": "textarea", "label": "Partner B: where it feels intrusive"}, {"id": "f4", "type": "textarea", "label": "A shared position we can both stand behind"}, {"id": "f5", "type": "textarea", "label": "How we will handle it if one side pushes back"}]'::jsonb, array['boundaries', 'conflict']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('couple-check-in-ritual-card', 'Couple Check-In Ritual Card', 'couples'::resource_kind, 'Sets a short, repeatable weekly check-in with the same four questions every time.', 'Build a low-effort ritual that catches small friction before it becomes a bigger conflict.', array['Couples']::text[], '15 minutes weekly', 'The value of this ritual is its repetition, so keep it to the same four questions every week rather than letting it expand into a full conversation. Sit facing each other, no phones, and take turns answering before either partner responds. Most couples find the habit itself, not any single answer, is what changes things over a few months.', '[{"id": "f0", "type": "textarea", "label": "Partner A: best part of my week"}, {"id": "f1", "type": "textarea", "label": "Partner A: hardest part of my week"}, {"id": "f2", "type": "textarea", "label": "Partner B: best part of my week"}, {"id": "f3", "type": "textarea", "label": "Partner B: hardest part of my week"}, {"id": "f4", "type": "textarea", "label": "Something I need from you this coming week"}]'::jsonb, array['routines', 'connection']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('worry-jar-craft', 'Worry Jar Craft', 'kids'::resource_kind, 'A child decorates a jar to hold written worries so they have somewhere to go besides the child''s head.', 'Give a child a concrete place to put a worry down instead of carrying it all day.', array['Children']::text[], '20 minutes', 'The parent helps the child decorate a small jar, then the two of them write worries on slips of paper together and drop them in whenever one comes up during the day. Set a regular time, after dinner works well, to open the jar together and sort which worries still need attention and which have already passed. The physical act of putting the worry in the jar is often more calming than solving it.', '[{"id": "f0", "type": "textarea", "label": "A worry I want to put in the jar"}, {"id": "f1", "type": "textarea", "label": "How big the worry feels (small, medium, big)"}, {"id": "f2", "type": "textarea", "label": "Does this worry need a grown-up''s help?"}, {"id": "f3", "type": "textarea", "label": "What I want to do with this worry now"}]'::jsonb, array['children', 'anxiety', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('breathing-pinwheel-craft', 'Breathing Pinwheel Craft', 'kids'::resource_kind, 'A child builds a paper pinwheel and practices slow breaths by making it spin gently.', 'Turn a breathing skill into something a child can see working, not just feel.', array['Children']::text[], '20 minutes', 'The parent helps the child assemble a simple paper pinwheel, then practices blowing on it together: fast breaths spin it wildly, slow steady breaths spin it smoothly. Once the child can make it spin slowly on purpose, they have a body skill they can use without the pinwheel later, since the breath pattern is what actually matters. Keep the pinwheel somewhere visible as a reminder.', '[{"id": "f0", "type": "textarea", "label": "How my breath made the pinwheel spin fast"}, {"id": "f1", "type": "textarea", "label": "How my breath made it spin slow and smooth"}, {"id": "f2", "type": "textarea", "label": "A time I could use slow breathing today"}, {"id": "f3", "type": "textarea", "label": "Where I will keep my pinwheel"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('my-safe-people-drawing', 'My Safe People Drawing', 'kids'::resource_kind, 'A child draws and labels the people they can go to when something feels wrong or scary.', 'Give a child a concrete, visual map of who is safe to tell.', array['Children']::text[], '20 minutes', 'The parent sits with the child while they draw and name each safe person, at home, at school and elsewhere, and what each one could help with. This works well as a general safety-building activity and also as a gentle check on whether the child can name enough safe adults across enough settings. If a child discloses anything concerning while drawing, the clinician follows their reporting duties before the session ends.', '[{"id": "f0", "type": "textarea", "label": "A safe person at home"}, {"id": "f1", "type": "textarea", "label": "A safe person at school"}, {"id": "f2", "type": "textarea", "label": "Another safe person somewhere else"}, {"id": "f3", "type": "textarea", "label": "What each person could help me with"}, {"id": "f4", "type": "textarea", "label": "How I would find them if I needed to"}]'::jsonb, array['children', 'safety', 'trust']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('feelings-weather-mobile-craft', 'Feelings Weather Mobile Craft', 'kids'::resource_kind, 'A child builds a hanging mobile with a symbol for each feeling-as-weather they experience.', 'Give a young child a playful, ongoing way to name and display shifting feelings.', array['Children']::text[], '30 minutes', 'The parent helps the child cut out and hang shapes for sun, rain, storm clouds and rainbows, each one paired with a feeling word, then the child can flip a marker to whichever shape matches their current mood. Revisiting the mobile daily builds feeling vocabulary without asking the child to sit still and talk about it. Keep it somewhere the child passes often, like a bedroom door.', '[{"id": "f0", "type": "textarea", "label": "The feeling that matches sun for me"}, {"id": "f1", "type": "textarea", "label": "The feeling that matches rain"}, {"id": "f2", "type": "textarea", "label": "The feeling that matches a storm cloud"}, {"id": "f3", "type": "textarea", "label": "The feeling that matches a rainbow"}, {"id": "f4", "type": "textarea", "label": "Which shape matches today"}]'::jsonb, array['children', 'play', 'emotion identification']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('brave-cape-craft', 'Brave Cape Craft', 'kids'::resource_kind, 'A child decorates a cape and names the brave moments that earn it a new patch or symbol.', 'Give a child a wearable, visible marker of moments they did something hard.', array['Children']::text[], '25 minutes', 'The parent helps the child make a simple cape from felt or fabric, then adds a new symbol each time the child names a brave moment from the week, trying something new, sitting with a big feeling, speaking up. The cape becomes a record the child can point to on harder days. Let the child choose what counts as brave rather than setting the bar for them.', '[{"id": "f0", "type": "textarea", "label": "A brave thing I did this week"}, {"id": "f1", "type": "textarea", "label": "How my body felt right before I did it"}, {"id": "f2", "type": "textarea", "label": "What I told myself to help"}, {"id": "f3", "type": "textarea", "label": "The symbol I want to add for this one"}, {"id": "f4", "type": "textarea", "label": "A brave thing I want to try next"}]'::jsonb, array['children', 'play', 'self-esteem']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('coping-skills-bingo', 'Coping Skills Bingo', 'game'::resource_kind, 'A bingo card of coping strategies the client marks off as they actually try them over a set stretch.', 'Turn practicing a range of coping skills into a game instead of a chore.', array['Adults', 'Teens', 'Groups']::text[], 'Two weeks', 'Give the client a bingo card with a different coping skill in each square and have them mark a square only once they have actually tried it, not just read it. A full row or a blackout can be a small, agreed reward. This works well in a group format too, comparing which skills different members marked off and why.', '[{"id": "f0", "type": "textarea", "label": "Skills I marked off this week"}, {"id": "f1", "type": "textarea", "label": "The one that surprised me most"}, {"id": "f2", "type": "textarea", "label": "The one I avoided and why"}, {"id": "f3", "type": "textarea", "label": "A square I want to try next"}, {"id": "f4", "type": "textarea", "label": "What a full row or blackout would mean to me"}]'::jsonb, array['coping skills', 'behavioral']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('thought-trap-trivia', 'Thought Trap Trivia', 'game'::resource_kind, 'A quiz-style game where players spot the thinking trap in short example statements.', 'Build quick recognition of common thinking traps through repetition and a bit of competition.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Read out short example statements, one at a time, and have players call out which thinking trap it shows: mind-reading, catastrophizing, all-or-nothing and so on, before revealing the answer. Keep score if the group likes competition, or just track it for fun. Close by asking each player for one real example from their own week that fits a trap from the game.', '[{"id": "f0", "type": "textarea", "label": "A trap I spotted quickly"}, {"id": "f1", "type": "textarea", "label": "One that tricked me"}, {"id": "f2", "type": "textarea", "label": "My own recent example of a thinking trap"}, {"id": "f3", "type": "textarea", "label": "Which trap shows up most for me"}, {"id": "f4", "type": "textarea", "label": "What I could say instead next time"}]'::jsonb, array['thinking traps', 'group', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('pass-the-prompt-circle-game', 'Pass the Prompt Circle Game', 'game'::resource_kind, 'A group passes a card with a reflection prompt around the circle, each person answering in turn.', 'Get a group talking with low pressure by giving everyone the same starting prompt.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Shuffle a set of open prompt cards, one clinician-approved question per card, and pass them around the circle so each member draws and answers one before passing the deck on. Members can pass on any card without explanation, which keeps the game safe for a quieter group. Debrief by asking which prompt was hardest to answer honestly.', '[{"id": "f0", "type": "textarea", "label": "A prompt I answered easily"}, {"id": "f1", "type": "textarea", "label": "A prompt I passed on or found hard"}, {"id": "f2", "type": "textarea", "label": "Something I heard from someone else that stuck with me"}, {"id": "f3", "type": "textarea", "label": "A prompt I would add to the deck"}]'::jsonb, array['group', 'communication']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('priority-ladder-card-game', 'Priority Ladder Card Game', 'game'::resource_kind, 'Players rank a mixed set of value cards into a ladder and defend their top choices to the group.', 'Make values clarification social and a little competitive instead of a solo worksheet.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Give each player the same deck of value cards and have them build a five-rung ladder from most to least important, then take turns defending why their top rung landed where it did. Other players can ask questions but not argue the ranking. This surfaces how differently people weigh the same set of values and often sparks better discussion than a private worksheet would.', '[{"id": "f0", "type": "textarea", "label": "My top value and why it is first"}, {"id": "f1", "type": "textarea", "label": "A value I ranked lower than I expected"}, {"id": "f2", "type": "textarea", "label": "A value a group member ranked that surprised me"}, {"id": "f3", "type": "textarea", "label": "Whether my ladder would look different next month"}]'::jsonb, array['values', 'group']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('roll-and-reflect-dice-game', 'Roll and Reflect Dice Game', 'game'::resource_kind, 'Rolling a die sends the client to a matching reflection prompt to answer before the next turn.', 'Add a low-stakes element of chance to a reflection exercise so it feels lighter.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'Number six prompts one through six, have the client or group roll a die, and answer whichever prompt comes up before rolling again for the next round. Repeats are fine and often land differently the second time. This is a light way to fill extra session time productively or to warm a quiet group up before a harder conversation.', '[{"id": "f0", "type": "textarea", "label": "Prompt one: what I rolled and how I answered"}, {"id": "f1", "type": "textarea", "label": "Prompt two"}, {"id": "f2", "type": "textarea", "label": "Prompt three"}, {"id": "f3", "type": "textarea", "label": "Which prompt I would want to roll again"}, {"id": "f4", "type": "textarea", "label": "Which prompt I would skip if I could"}]'::jsonb, array['group', 'coping skills']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('grounding-object-kit-sheet', 'Grounding Object Kit Sheet', 'worksheet'::resource_kind, 'Helps a client choose and plan how to use a small set of grounding objects when memories intrude.', 'Give the client something physical to reach for that pulls attention back to the present.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client pick three or four small objects, a stone, a scented item, something textured, that reliably pull attention into the present, and write exactly how they will use each one. Keep this to planning and rehearsal in session rather than asking the client to relive a memory to test it. Review which objects actually got used between sessions and swap out ones that did not help.', '[{"id": "f0", "type": "textarea", "label": "Object one and how I will use it"}, {"id": "f1", "type": "textarea", "label": "Object two and how I will use it"}, {"id": "f2", "type": "textarea", "label": "Object three and how I will use it"}, {"id": "f3", "type": "textarea", "label": "Where I will keep them"}, {"id": "f4", "type": "textarea", "label": "A moment this week I could have used one"}]'::jsonb, array['PTSD and trauma', 'grounding', 'coping skills']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('safety-cue-recognition-sheet', 'Safety Cue Recognition Sheet', 'cbt'::resource_kind, 'Lists the present-day cues a client''s body reads as danger and the safety facts that counter them.', 'Help the client''s body catch up to the fact that a past danger is not today''s danger.', array['Adults']::text[], '25 minutes', 'List a handful of everyday cues, a loud noise, a certain tone of voice, that trigger a body response left over from the past, and next to each one write the concrete facts of the present moment that are actually true right now. This stays a grounding and orienting exercise, not a request to describe what happened in detail. Keep the pace slow and check in on distress throughout.', '[{"id": "f0", "type": "textarea", "label": "A cue that triggers a strong body response"}, {"id": "f1", "type": "textarea", "label": "What my body does in that moment"}, {"id": "f2", "type": "textarea", "label": "The facts that are true about right now"}, {"id": "f3", "type": "textarea", "label": "Something in the room I can point to that proves it"}, {"id": "f4", "type": "textarea", "label": "How I will remind myself of this next time"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('present-moment-safety-scan', 'Present-Moment Safety Scan', 'act'::resource_kind, 'A brief guided scan of the five senses to anchor the client in the current, safe environment.', 'Bring a client''s attention fully into the present room when the past starts to feel close.', array['Adults', 'Teens']::text[], '10 minutes', 'Walk the client through naming what they can currently see, hear, feel underfoot, smell and touch, slowly and without rushing to the next sense. This is a stabilizing, present-focused practice and is meant to be run in session first before the client tries it alone. Pair it with a brief word for the client to use as a private cue to start the scan on their own later.', '[{"id": "f0", "type": "textarea", "label": "What I can see right now"}, {"id": "f1", "type": "textarea", "label": "What I can hear right now"}, {"id": "f2", "type": "textarea", "label": "What I feel under my feet or in my hands"}, {"id": "f3", "type": "textarea", "label": "What I can smell or taste"}, {"id": "f4", "type": "textarea", "label": "A word I will use to remind myself to do this"}]'::jsonb, array['PTSD and trauma', 'grounding', 'core ACT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('window-of-tolerance-check-in-card', 'Window of Tolerance Check-In Card', 'dbt'::resource_kind, 'A quick, repeatable check on whether a client is inside, above or below their window of tolerance.', 'Give the client a fast read on their own state so they can choose a matching skill.', array['Adults', 'Teens']::text[], 'Five minutes daily', 'Teach the client to notice whether they feel keyed up, shut down or steady, and to name it against their own window rather than judging it. Each state points toward a different skill: calming for keyed up, gentle activation for shut down, nothing needed when steady. If the check-in ever points toward thoughts of self-harm, that is worked through in session and 988 (call or text) is available right away, not left for later.', '[{"id": "f0", "type": "textarea", "label": "How keyed up, shut down or steady I feel"}, {"id": "f1", "type": "textarea", "label": "What in my body tells me that"}, {"id": "f2", "type": "textarea", "label": "The skill that matches this state"}, {"id": "f3", "type": "textarea", "label": "If thoughts of harming myself show up, what I will do (988, call or text)"}, {"id": "f4", "type": "textarea", "label": "How I feel after using the matching skill"}]'::jsonb, array['PTSD and trauma', 'window of tolerance', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-support-signals-sheet', 'Partner Support Signals Sheet', 'couples'::resource_kind, 'Helps a couple agree on quiet signals for when one partner needs space or closeness after a hard moment.', 'Give partners a shared, low-pressure way to ask for and offer support around trauma responses.', array['Couples']::text[], '20 minutes', 'Trauma responses do not always come with words attached, so this gives the couple two or three simple signals, a hand on the shoulder, a specific phrase, for asking for space and for asking for closeness. Practice using the signals outside of a hard moment first so they feel familiar under stress. Review after a few weeks and adjust anything that was not landing the way it was meant to.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my signal for needing space"}, {"id": "f1", "type": "textarea", "label": "Partner A: my signal for needing closeness"}, {"id": "f2", "type": "textarea", "label": "Partner B: my signal for needing space"}, {"id": "f3", "type": "textarea", "label": "Partner B: my signal for needing closeness"}, {"id": "f4", "type": "textarea", "label": "How this week went using the signals"}]'::jsonb, array['PTSD and trauma', 'support', 'couples']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('worry-volume-dial-craft', 'Worry Volume Dial Craft', 'kids'::resource_kind, 'A child builds a paper dial to show how loud a worry feels and practices turning it down.', 'Give a young child a hands-on way to rate and lower a worry''s intensity.', array['Children']::text[], '20 minutes', 'The parent helps the child make a simple paper dial with a spinning arrow from quiet to loud, then the child points to how loud a current worry feels. Practice a calming skill together, slow breathing works well, and have the child move the dial down afterward to see the change. Keep the dial handy so the child can use it independently once the routine feels familiar.', '[{"id": "f0", "type": "textarea", "label": "A worry I have right now"}, {"id": "f1", "type": "textarea", "label": "Where the dial points before I calm down"}, {"id": "f2", "type": "textarea", "label": "The calming skill I tried"}, {"id": "f3", "type": "textarea", "label": "Where the dial points after"}]'::jsonb, array['anxiety', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('worry-or-wonder-sorting-game', 'Worry or Wonder Sorting Game', 'game'::resource_kind, 'Players sort a stack of statement cards into worries versus simple wonderings, then discuss the split.', 'Practice telling anxious prediction apart from ordinary curiosity in a light, repeatable format.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Prepare a deck of short cards, some phrased as anxious predictions and some as neutral curiosity, and have players sort each one into a worry pile or a wonder pile before discussing any they disagreed on. The discussion is usually where the learning happens, since the line between the two is not always obvious. Close by having each player add one real card from their own week.', '[{"id": "f0", "type": "textarea", "label": "A card I sorted easily"}, {"id": "f1", "type": "textarea", "label": "A card the group disagreed on"}, {"id": "f2", "type": "textarea", "label": "My own worry from this week, as a card"}, {"id": "f3", "type": "textarea", "label": "How I could reword it as a wonder instead"}]'::jsonb, array['anxiety', 'group', 'thinking traps']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('worst-case-best-case-likely-case-sheet', 'Worst Case Best Case Likely Case Sheet', 'worksheet'::resource_kind, 'Lays out three versions of an anxious prediction side by side to widen a narrowed focus.', 'Pull a client''s attention off the worst case alone and onto the full range of outcomes.', array['Adults', 'Teens']::text[], '15 minutes', 'Anxious thinking tends to fixate on the worst case as if it were the only possible outcome, so this asks the client to write the worst, best and most likely case for the same situation side by side. Ask which case the client has actually been planning their day around. Most clients notice the likely case gets the least airtime despite being the most probable.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The worst case"}, {"id": "f2", "type": "textarea", "label": "The best case"}, {"id": "f3", "type": "textarea", "label": "The most likely case"}, {"id": "f4", "type": "textarea", "label": "Which one I have been acting as if were certain"}, {"id": "f5", "type": "textarea", "label": "How I want to act given the likely case"}]'::jsonb, array['anxiety', 'thinking traps', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('uncertainty-tolerance-ladder', 'Uncertainty Tolerance Ladder', 'cbt'::resource_kind, 'Ranks situations by how much uncertainty they carry and schedules practice sitting with each rung.', 'Build a client''s capacity to tolerate not knowing, one deliberately chosen situation at a time.', array['Adults', 'Teens']::text[], 'One week', 'List several everyday situations that involve some uncertainty, from mild to significant, and rank them into a ladder. Starting on a low rung, have the client deliberately sit with the not-knowing rather than seeking reassurance or certainty, and log how the discomfort moved over time without any action taken. Move up a rung only once the lower one feels manageable.', '[{"id": "f0", "type": "textarea", "label": "Situations with uncertainty, ranked low to high"}, {"id": "f1", "type": "textarea", "label": "The rung I will start with"}, {"id": "f2", "type": "textarea", "label": "What I normally do to get rid of the uncertainty"}, {"id": "f3", "type": "textarea", "label": "What I will do instead this time"}, {"id": "f4", "type": "textarea", "label": "How the discomfort changed without me acting on it"}]'::jsonb, array['anxiety', 'core CBT', 'exposure']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-passenger-practice', 'Anxious Mind as Passenger Practice', 'act'::resource_kind, 'Uses the bus-driver metaphor to practice acting on values while an anxious voice keeps talking.', 'Let the client keep moving toward what matters while anxious thoughts run in the background.', array['Adults', 'Teens']::text[], '15 minutes', 'Introduce the image of the client as the driver and the anxious mind as a loud passenger who does not get to grab the wheel. Ask what direction the client wants to drive regardless of what the passenger says, then plan one small action this week that moves that direction even with the passenger talking. The goal is not a quieter passenger but a driver who keeps driving.', '[{"id": "f0", "type": "textarea", "label": "What the anxious passenger has been saying lately"}, {"id": "f1", "type": "textarea", "label": "The direction I want to keep driving"}, {"id": "f2", "type": "textarea", "label": "One action this week in that direction"}, {"id": "f3", "type": "textarea", "label": "What I expect the passenger to say about it"}, {"id": "f4", "type": "textarea", "label": "How I will keep driving anyway"}]'::jsonb, array['anxiety', 'core ACT', 'values']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-low-mood-planner', 'Opposite Action for Low Mood Planner', 'dbt'::resource_kind, 'Plans a small opposite action to take when the urge to withdraw sets in.', 'Give the client a concrete counter-move for the pull to isolate and stay still.', array['Adults', 'Teens']::text[], 'One week', 'When low mood pulls toward withdrawing, staying in bed, canceling plans, this plans a small, opposite action in advance for a handful of likely moments in the coming week. Pick actions genuinely doable at a low-energy baseline rather than ambitious ones, since an unreachable plan just becomes another failure. If low mood ever comes with thoughts of ending things, that gets addressed in session directly and 988 (call or text) stays visible as an option, not something saved for later.', '[{"id": "f0", "type": "textarea", "label": "A likely moment this week the urge to withdraw will show up"}, {"id": "f1", "type": "textarea", "label": "The opposite action I will try"}, {"id": "f2", "type": "textarea", "label": "How doable this feels, out of ten"}, {"id": "f3", "type": "textarea", "label": "If thoughts of ending things show up, what I will do (988, call or text)"}, {"id": "f4", "type": "textarea", "label": "How the opposite action actually went"}]'::jsonb, array['depression', 'behavioral activation', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-support-without-fixing-sheet', 'Partner Support Without Fixing Sheet', 'couples'::resource_kind, 'Helps the non-depressed partner practice offering support that does not slide into trying to fix the mood.', 'Give a supporting partner language that helps without adding pressure to feel better.', array['Couples']::text[], '20 minutes', 'The partner supporting someone through low mood often defaults to solutions, which can land as pressure rather than help. This has both partners name what support actually helps, sitting nearby, a specific task taken off the plate, versus what tends to backfire, being told to think positive. Revisit after a hard week to see what held up.', '[{"id": "f0", "type": "textarea", "label": "Partner with low mood: what support actually helps"}, {"id": "f1", "type": "textarea", "label": "Partner with low mood: what tends to backfire"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what I have been trying"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what I will try instead"}, {"id": "f4", "type": "textarea", "label": "How this week went"}]'::jsonb, array['depression', 'support', 'couples']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('small-joys-treasure-hunt', 'Small Joys Treasure Hunt', 'kids'::resource_kind, 'A child hunts around the house or yard for small things that gave a spark of good feeling that day.', 'Help a child with low mood notice small good moments instead of only the heavy ones.', array['Children']::text[], '20 minutes', 'The parent walks with the child on a short hunt for anything, a toy, a color, a sound, that gave even a small spark of good feeling that day, collecting them in a basket or on a list. This is not about forcing cheerfulness but about practicing noticing, since low mood tends to filter small good moments out entirely. Keep the hunt short and let the child lead which items count.', '[{"id": "f0", "type": "textarea", "label": "Something I found that gave a small good feeling"}, {"id": "f1", "type": "textarea", "label": "Another thing I found"}, {"id": "f2", "type": "textarea", "label": "One more thing"}, {"id": "f3", "type": "textarea", "label": "Which one I liked finding the most"}]'::jsonb, array['depression', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('would-you-rather-low-energy-edition', 'Would You Rather: Low-Energy Edition', 'game'::resource_kind, 'A would-you-rather game built around small, low-effort choices to practice deciding when motivation is low.', 'Keep decision-making muscles active with playful, genuinely low-stakes choices.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'Low mood often makes even small decisions feel heavy, so this uses playful would-you-rather questions built around low-effort choices, a walk or a shower, tea or water, to keep the decision muscle moving without real stakes attached. Keep the tone light and let any answer be fine. Close by picking one real low-effort choice to actually follow through on today.', '[{"id": "f0", "type": "textarea", "label": "A would-you-rather I answered easily"}, {"id": "f1", "type": "textarea", "label": "One that was surprisingly hard"}, {"id": "f2", "type": "textarea", "label": "A real low-effort choice I will make today"}, {"id": "f3", "type": "textarea", "label": "How making small choices felt overall"}]'::jsonb, array['depression', 'group', 'behavioral activation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('minimum-viable-day-planner', 'Minimum Viable Day Planner', 'worksheet'::resource_kind, 'Sets a bare-minimum version of the day''s tasks for when energy and motivation are at their lowest.', 'Lower the bar enough on the hardest days that the client can still meet it.', array['Adults', 'Teens']::text[], '10 minutes', 'On a hard-energy day, have the client write the smallest possible version of each task that still counts as done, one dish instead of the whole sink, five minutes instead of a full workout. The point is a day the client can actually complete, which protects momentum better than an ambitious plan abandoned by noon. Revisit the ordinary version of the plan once energy returns.', '[{"id": "f0", "type": "textarea", "label": "Today''s tasks, at full size"}, {"id": "f1", "type": "textarea", "label": "The bare-minimum version of each"}, {"id": "f2", "type": "textarea", "label": "Which minimum version I will actually do"}, {"id": "f3", "type": "textarea", "label": "How it felt to lower the bar"}, {"id": "f4", "type": "textarea", "label": "What tomorrow''s minimum might look like"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('task-friction-point-log', 'Task Friction Point Log', 'cbt'::resource_kind, 'Identifies the exact moment a task gets abandoned to target the real sticking point.', 'Find where a task actually breaks down instead of treating all stalled tasks the same way.', array['Adults', 'Teens']::text[], 'One week', 'Rather than asking why a task did not get finished in general, have the client log the exact moment it stalled, at the start, midway, or right before finishing, across several tasks. Different friction points call for different fixes: a starting problem needs a smaller first step, a midpoint stall needs a check-in cue. Use the pattern across entries to pick one fix to try next.', '[{"id": "f0", "type": "textarea", "label": "A task I did not finish"}, {"id": "f1", "type": "textarea", "label": "The exact moment it stalled"}, {"id": "f2", "type": "textarea", "label": "What was happening right before that moment"}, {"id": "f3", "type": "textarea", "label": "Where most of my stalls tend to happen"}, {"id": "f4", "type": "textarea", "label": "One fix to try for that point"}]'::jsonb, array['ADHD', 'core CBT', 'self-monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('values-based-focus-anchor', 'Values-Based Focus Anchor', 'act'::resource_kind, 'Connects a dull or difficult task back to the value it actually serves, to renew willingness to do it.', 'Use values, not willpower alone, to get the client back to a task that keeps losing their attention.', array['Adults', 'Teens']::text[], '15 minutes', 'Attention often drifts fastest from tasks that feel disconnected from anything that matters, so this asks the client to name a genuine, personal value the task connects to, even a boring one like filing paperwork. Write the connection down somewhere visible before starting the task. This will not fix attention on its own but gives the client something to return to when it wanders.', '[{"id": "f0", "type": "textarea", "label": "The task I keep losing focus on"}, {"id": "f1", "type": "textarea", "label": "A value this task actually serves"}, {"id": "f2", "type": "textarea", "label": "How I will keep that value visible while I work"}, {"id": "f3", "type": "textarea", "label": "What I will do when my attention drifts"}, {"id": "f4", "type": "textarea", "label": "How this attempt went"}]'::jsonb, array['ADHD', 'core ACT', 'values']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('body-double-session-planner', 'Body Double Session Planner', 'dbt'::resource_kind, 'Plans a body-doubling session, pairing with another person present while doing a hard task.', 'Use another person''s quiet presence to make starting and sticking with a task easier.', array['Adults', 'Teens']::text[], '30 to 60 minutes', 'Body doubling, working alongside another person who is present but not necessarily helping directly, can make starting and staying with a task noticeably easier for some clients. Plan the specific task, the person, and the setting in advance rather than leaving it to whenever motivation shows up. Note afterward whether the presence of another person actually changed the outcome.', '[{"id": "f0", "type": "textarea", "label": "The task I need to get through"}, {"id": "f1", "type": "textarea", "label": "Who I will ask to be my body double"}, {"id": "f2", "type": "textarea", "label": "When and where this will happen"}, {"id": "f3", "type": "textarea", "label": "How the session actually went"}, {"id": "f4", "type": "textarea", "label": "Whether I want to make this a regular practice"}]'::jsonb, array['ADHD', 'skills', 'behavioral']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-task-handoff-system', 'Partner Task Handoff System', 'couples'::resource_kind, 'Builds a shared, visible system for handing off household tasks that keep getting forgotten.', 'Replace a running mental tally of dropped tasks with a system both partners can see.', array['Couples']::text[], '20 minutes', 'A partner with attention difficulty is not choosing to forget, and a partner tracking everything mentally is not choosing to resent it, so this builds a shared visible list, a board or shared app works, that takes the tracking out of anyone''s head. Assign tasks explicitly rather than leaving them implied. Review together after two weeks and adjust what is not working.', '[{"id": "f0", "type": "textarea", "label": "Tasks that keep getting dropped"}, {"id": "f1", "type": "textarea", "label": "Where we will keep the shared list"}, {"id": "f2", "type": "textarea", "label": "How a task gets marked done"}, {"id": "f3", "type": "textarea", "label": "What we will do when something still gets missed"}, {"id": "f4", "type": "textarea", "label": "How the system felt after two weeks"}]'::jsonb, array['ADHD', 'couples', 'routines']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('focus-fort-building-activity', 'Focus Fort Building Activity', 'kids'::resource_kind, 'A child builds a cozy focus fort and practices using it for one short, chosen task.', 'Give a child with a busy attention a physical space that signals it is time to focus.', array['Children']::text[], '25 minutes', 'The parent and child build a simple blanket fort or designated corner together, then the child picks one short task, a puzzle, coloring, a worksheet, to try inside it with a timer set for a few minutes. The fort works as a physical cue rather than a magic fix, so keep first attempts short and build up gradually. Praise the attempt to start, not just finishing.', '[{"id": "f0", "type": "textarea", "label": "What my focus fort looks like"}, {"id": "f1", "type": "textarea", "label": "The task I chose to try inside it"}, {"id": "f2", "type": "textarea", "label": "How long I lasted before the timer"}, {"id": "f3", "type": "textarea", "label": "What helped me stay in the fort"}, {"id": "f4", "type": "textarea", "label": "What I want to try next time"}]'::jsonb, array['ADHD', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('urge-timing-dice-game', 'Urge Timing Dice Game', 'game'::resource_kind, 'Rolling a die assigns a wait interval to practice riding out an urge before deciding whether to act.', 'Build tolerance for delay by practicing short, low-stakes waits attached to an urge.', array['Adults', 'Teens', 'Groups']::text[], '15 minutes', 'When an urge shows up, roll a die to set a wait interval, one to six minutes, and have the client simply notice the urge without acting until the timer runs out, then decide freely. Playing this on a low-stakes urge in session first builds the habit before it needs to hold under real pressure. Log how the urge''s intensity changed just from the delay.', '[{"id": "f0", "type": "textarea", "label": "The urge I practiced with"}, {"id": "f1", "type": "textarea", "label": "The number I rolled and the wait it set"}, {"id": "f2", "type": "textarea", "label": "How intense the urge felt at the start"}, {"id": "f3", "type": "textarea", "label": "How intense it felt once the timer ended"}, {"id": "f4", "type": "textarea", "label": "What I decided once the wait was over"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('high-risk-situation-map', 'High-Risk Situation Map', 'worksheet'::resource_kind, 'Maps out the places, people and times that reliably raise urges around substance use.', 'Give the client a clear picture of their own risk landscape to plan around.', array['Adults']::text[], '25 minutes', 'Have the client list specific situations, not vague categories, where urges around substance use reliably show up: a particular bar, a certain time of night, a specific person. For each one, note whether it can be avoided, changed, or needs a coping plan instead. This map is meant to be revisited and updated, not written once and filed away.', '[{"id": "f0", "type": "textarea", "label": "A place that raises urges"}, {"id": "f1", "type": "textarea", "label": "A person or group that raises urges"}, {"id": "f2", "type": "textarea", "label": "A time of day or week that raises urges"}, {"id": "f3", "type": "textarea", "label": "Which of these I can avoid or change"}, {"id": "f4", "type": "textarea", "label": "The coping plan for the ones I cannot avoid"}]'::jsonb, array['addiction', 'urges', 'monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('substance-use-function-sheet', 'Substance Use Function Sheet', 'cbt'::resource_kind, 'Identifies what substance use has actually been doing for the client, situation by situation.', 'Understand the function substance use serves so a real alternative can be found for it.', array['Adults']::text[], '25 minutes', 'For several recent instances of substance use, have the client write what it was doing for them in that moment, numbing, socializing, sleep, relief from a specific feeling. Once the function is named, brainstorm one alternative that could serve the same function without the substance. Not every function will have an easy substitute, and naming that honestly is still useful.', '[{"id": "f0", "type": "textarea", "label": "A recent instance of substance use"}, {"id": "f1", "type": "textarea", "label": "What it was doing for me in that moment"}, {"id": "f2", "type": "textarea", "label": "The feeling or need underneath it"}, {"id": "f3", "type": "textarea", "label": "An alternative that could serve the same function"}, {"id": "f4", "type": "textarea", "label": "How realistic that alternative feels"}]'::jsonb, array['addiction', 'urges', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('values-beyond-substance-use-map', 'Values Beyond Substance Use Map', 'act'::resource_kind, 'Maps what matters to the client across life domains, separate from anything tied to substance use.', 'Reconnect the client to a wider set of values than the ones substance use has been narrowing life around.', array['Adults']::text[], '25 minutes', 'Substance use tends to narrow life down to a small number of values, and this widens the view back out across relationships, health, work, and personal growth, asking what the client wants each domain to look like. Compare the map to how time actually gets spent now. Pick one domain to invest a small amount of time in this week, independent of urges either way.', '[{"id": "f0", "type": "textarea", "label": "What matters to me in relationships"}, {"id": "f1", "type": "textarea", "label": "What matters to me in health"}, {"id": "f2", "type": "textarea", "label": "What matters to me in work or purpose"}, {"id": "f3", "type": "textarea", "label": "How my time actually splits across these now"}, {"id": "f4", "type": "textarea", "label": "One domain I will invest in this week"}]'::jsonb, array['addiction', 'core ACT', 'values']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('urge-surf-and-log-card', 'Urge Surf and Log Card', 'dbt'::resource_kind, 'A pocket card for riding out an urge in the moment, with a short log to fill in afterward.', 'Give the client a fast, in-the-moment skill for an urge plus a record to review in session.', array['Adults', 'Teens']::text[], '10 minutes per use', 'The card walks the client through noticing where the urge shows up in the body, breathing through the peak, and reminding themselves that urges rise and fall whether or not they act on them. Fill in the short log afterward while it is fresh. Bring the week''s cards to session to look for patterns in timing, intensity and what helped.', '[{"id": "f0", "type": "textarea", "label": "Where I felt the urge in my body"}, {"id": "f1", "type": "textarea", "label": "How intense it was at the peak (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "How long it took to pass"}, {"id": "f3", "type": "textarea", "label": "What I did instead of acting on it"}, {"id": "f4", "type": "textarea", "label": "How intense it was five minutes later"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('fair-fight-ground-rules-sheet', 'Fair Fight Ground Rules Sheet', 'couples'::resource_kind, 'Has a couple agree in advance on what is and is not allowed during a heated disagreement.', 'Set boundaries around conflict before anger is running the conversation.', array['Couples']::text[], '20 minutes', 'Agree together, outside of a conflict, on a short list of ground rules: no name-calling, no bringing up old fights, a pause is always allowed. Both partners sign off on the same list so it is a shared agreement rather than one partner''s rule for the other. Revisit the list after it gets tested by a real disagreement and adjust anything that did not hold.', '[{"id": "f0", "type": "textarea", "label": "Rule one we both agree to"}, {"id": "f1", "type": "textarea", "label": "Rule two"}, {"id": "f2", "type": "textarea", "label": "Rule three"}, {"id": "f3", "type": "textarea", "label": "What happens if a rule gets broken"}, {"id": "f4", "type": "textarea", "label": "How the rules held up during a recent disagreement"}]'::jsonb, array['anger management', 'conflict', 'couples']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('anger-thermometer-craft', 'Anger Thermometer Craft', 'kids'::resource_kind, 'A child builds a color-coded thermometer to show anger climbing and practices a cool-down at each level.', 'Give a child a visual, hands-on way to catch anger building before it peaks.', array['Children']::text[], '20 minutes', 'The parent helps the child color a paper thermometer from green at the bottom to red at the top, marking a body clue at each level, and agrees on one cool-down move for the yellow zone before red is reached. Practice pointing to the thermometer during a calm moment first so it is familiar when it is actually needed. Praise catching the yellow zone even more than staying calm at green.', '[{"id": "f0", "type": "textarea", "label": "What my body feels like at green"}, {"id": "f1", "type": "textarea", "label": "What it feels like at yellow"}, {"id": "f2", "type": "textarea", "label": "What it feels like at red"}, {"id": "f3", "type": "textarea", "label": "My cool-down move for yellow"}, {"id": "f4", "type": "textarea", "label": "A time this week I caught myself at yellow"}]'::jsonb, array['anger management', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('anger-volume-charades', 'Anger Volume Charades', 'game'::resource_kind, 'Players act out anger at different intensities without words while others guess the level.', 'Practice recognizing anger''s different intensities in a playful, low-stakes format.', array['Teens', 'Groups']::text[], '20 minutes', 'Players take turns silently acting out anger at a level from one to ten while the group guesses the number, then discuss what physical cues gave it away. This builds recognition skills for both the player''s own body signals and for reading intensity in others. Close by asking each player to name their own real early-warning cue for anger.', '[{"id": "f0", "type": "textarea", "label": "A level I guessed correctly"}, {"id": "f1", "type": "textarea", "label": "A level that was hard to read"}, {"id": "f2", "type": "textarea", "label": "My own early body cue for anger"}, {"id": "f3", "type": "textarea", "label": "What level I usually notice it at versus what level I would like to notice it"}]'::jsonb, array['anger management', 'group', 'emotion identification']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('anger-aftermath-repair-checklist', 'Anger Aftermath Repair Checklist', 'worksheet'::resource_kind, 'Walks through repairing a relationship after an angry outburst, step by step.', 'Give the client a concrete sequence for making amends instead of just feeling bad afterward.', array['Adults', 'Teens']::text[], '20 minutes', 'After an angry outburst, guilt alone rarely fixes the relationship, so this walks through naming what happened without excusing it, acknowledging the impact on the other person, and offering a specific repair rather than a vague apology. Have the client draft the actual words they will use. Follow up next session on whether the repair happened and how it landed.', '[{"id": "f0", "type": "textarea", "label": "What happened, plainly stated"}, {"id": "f1", "type": "textarea", "label": "The impact on the other person"}, {"id": "f2", "type": "textarea", "label": "What I am not going to excuse away"}, {"id": "f3", "type": "textarea", "label": "The specific repair I will offer"}, {"id": "f4", "type": "textarea", "label": "The words I will actually use"}]'::jsonb, array['anger management', 'repair', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('anger-function-analysis', 'Anger Function Analysis', 'cbt'::resource_kind, 'Examines what an anger outburst accomplished for the client, beyond the immediate release.', 'Find what anger has been doing functionally so a less costly option can take its place.', array['Adults']::text[], '25 minutes', 'For a recent outburst, have the client identify what it actually accomplished, did it get someone to back off, did it end a conversation, did it release built-up tension, since anger usually is doing something even when it also creates a cost. Once the function is clear, brainstorm one way to get that same function more cheaply. This reframes anger as workable rather than simply bad.', '[{"id": "f0", "type": "textarea", "label": "A recent outburst"}, {"id": "f1", "type": "textarea", "label": "What it accomplished in the moment"}, {"id": "f2", "type": "textarea", "label": "What it cost afterward"}, {"id": "f3", "type": "textarea", "label": "A cheaper way to get the same result"}, {"id": "f4", "type": "textarea", "label": "How I will try that instead next time"}]'::jsonb, array['anger management', 'core CBT', 'formulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('thought-is-not-a-command-practice', 'Thought Is Not a Command Practice', 'act'::resource_kind, 'Practices letting an intrusive thought pass through without acting on it or arguing with it.', 'Loosen the pull to act on or fight an intrusive thought by practicing simply letting it pass.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client notice an intrusive thought, name it out loud as just a thought, and practice neither arguing with it nor following its instruction, letting it sit there instead. This is uncomfortable at first and that discomfort is expected, not a sign it is going wrong. Track how the urge to respond to the thought changes the more it is simply allowed to pass.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought"}, {"id": "f1", "type": "textarea", "label": "The urge it came with"}, {"id": "f2", "type": "textarea", "label": "What I normally do in response"}, {"id": "f3", "type": "textarea", "label": "What I did instead this time"}, {"id": "f4", "type": "textarea", "label": "How the urge changed by not responding"}]'::jsonb, array['OCD', 'core ACT', 'defusion']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('ritual-delay-ladder', 'Ritual Delay Ladder', 'dbt'::resource_kind, 'Builds a gradual ladder of delay times before a ritual, from short to long.', 'Stretch the gap between urge and ritual gradually rather than trying to stop it outright.', array['Adults', 'Teens']::text[], 'One to two weeks', 'Rather than asking a client to stop a ritual entirely, this builds a ladder of delay times, starting at whatever is currently manageable and lengthening gradually as each rung becomes tolerable. Log the urge intensity at the start and end of each delay to show the client their own data on urges settling with time. Move to the next rung only once the current one feels steady.', '[{"id": "f0", "type": "textarea", "label": "The ritual I am working on delaying"}, {"id": "f1", "type": "textarea", "label": "My current delay time"}, {"id": "f2", "type": "textarea", "label": "Urge intensity at the start of the delay"}, {"id": "f3", "type": "textarea", "label": "Urge intensity at the end of the delay"}, {"id": "f4", "type": "textarea", "label": "The next delay time I will try"}]'::jsonb, array['OCD', 'urges', 'distress tolerance']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-response-to-rituals-sheet', 'Partner Response to Rituals Sheet', 'couples'::resource_kind, 'Helps a partner identify where they have been participating in a loved one''s rituals and plan a different response.', 'Reduce a partner''s role in maintaining rituals without leaving the client unsupported.', array['Couples']::text[], '25 minutes', 'Partners often get pulled into providing reassurance or performing part of a ritual themselves, which can end up maintaining the very pattern everyone wants to reduce. Have both partners name where this has been happening and agree together, gradually, on a different, supportive response that does not involve joining the ritual. Go slowly and revisit often, since this shift can be hard on both partners.', '[{"id": "f0", "type": "textarea", "label": "Partner with intrusive thoughts: rituals my partner has been part of"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: what I have been doing to help"}, {"id": "f2", "type": "textarea", "label": "What we will try instead"}, {"id": "f3", "type": "textarea", "label": "How this shift feels for each of us"}, {"id": "f4", "type": "textarea", "label": "How the new approach went this week"}]'::jsonb, array['OCD', 'family accommodation', 'couples']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('worry-bug-jar-craft', 'Worry Bug Jar Craft', 'kids'::resource_kind, 'A child draws a worry bug for a repeating intrusive thought and puts it in a jar instead of acting on it.', 'Give a child a playful, externalized way to hold a repeating worry-thought without needing to act on it.', array['Children']::text[], '20 minutes', 'The parent helps the child draw a small bug representing a repeating unwanted thought, names it something silly, and practices putting the paper bug in a jar instead of doing whatever the thought is asking for. This is a stabilizing, externalizing activity, not a way to explain away the thought, and the parent stays close throughout. Praise noticing the bug even when the child cannot yet resist responding to it.', '[{"id": "f0", "type": "textarea", "label": "What my worry bug looks like"}, {"id": "f1", "type": "textarea", "label": "What it tries to get me to do"}, {"id": "f2", "type": "textarea", "label": "What I did instead of listening to it"}, {"id": "f3", "type": "textarea", "label": "How it felt to put it in the jar"}]'::jsonb, array['OCD', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('certainty-or-not-sorting-game', 'Certainty or Not Sorting Game', 'game'::resource_kind, 'Players sort statement cards into things that can be known for certain and things that cannot.', 'Practice tolerating the difference between certainty and near-certainty in a playful format.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Prepare cards with everyday statements, some genuinely certain, most only near-certain, and have players sort them while discussing how confident is confident enough to act on. This builds practice sitting with the small gap between near-certain and fully certain, which is often where intrusive doubt lives. Close with one real example from the client''s own week.', '[{"id": "f0", "type": "textarea", "label": "A card that was genuinely certain"}, {"id": "f1", "type": "textarea", "label": "A card that was only near-certain"}, {"id": "f2", "type": "textarea", "label": "How confident I usually need to feel before I can act"}, {"id": "f3", "type": "textarea", "label": "My own recent example of near-certainty I could practice sitting with"}]'::jsonb, array['OCD', 'group', 'uncertainty']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('panic-sensation-checklist', 'Panic Sensation Checklist', 'worksheet'::resource_kind, 'Lists the specific body sensations a client notices during a panic episode, in order of appearance.', 'Give the client a clear, ordered map of their own panic sensations to work with.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client recall a recent episode and list every sensation in the order it showed up, racing heart, tight chest, dizziness, rather than a general description. Ordering the sensations often reveals a consistent early sign the client had not noticed before, which becomes the cue to use a coping skill earliest. Compare across a couple of episodes to confirm the pattern.', '[{"id": "f0", "type": "textarea", "label": "The first sensation I notice"}, {"id": "f1", "type": "textarea", "label": "What comes next"}, {"id": "f2", "type": "textarea", "label": "What comes after that"}, {"id": "f3", "type": "textarea", "label": "The peak sensation"}, {"id": "f4", "type": "textarea", "label": "The earliest sign I could use as my cue"}]'::jsonb, array['panic attacks', 'monitoring', 'formulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('catastrophic-misreading-correction-sheet', 'Catastrophic Misreading Correction Sheet', 'cbt'::resource_kind, 'Pairs each panic sensation with the catastrophic thought attached to it and a more accurate alternative.', 'Separate a physical sensation from the frightening meaning the client''s mind attaches to it.', array['Adults', 'Teens']::text[], '20 minutes', 'For each sensation on the client''s panic list, write down the catastrophic interpretation that shows up automatically, alongside a more accurate, benign explanation for the same sensation. Reading both versions side by side, repeatedly, helps loosen the automatic link between sensation and catastrophe over time. This pairs well with any interoceptive practice already underway.', '[{"id": "f0", "type": "textarea", "label": "A sensation from a recent episode"}, {"id": "f1", "type": "textarea", "label": "The catastrophic thought attached to it"}, {"id": "f2", "type": "textarea", "label": "A more accurate explanation for the same sensation"}, {"id": "f3", "type": "textarea", "label": "How believable each explanation feels right now"}, {"id": "f4", "type": "textarea", "label": "What I will remind myself next time"}]'::jsonb, array['panic attacks', 'core CBT', 'thinking traps']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('willingness-to-feel-panic-practice', 'Willingness to Feel Panic Practice', 'act'::resource_kind, 'Practices making room for panic sensations rather than fighting them, in small deliberate amounts.', 'Reduce the fight against panic sensations, since the fight often intensifies them further.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client deliberately bring on a mild version of a panic sensation, through brief exercise or breath holding, in session, and practice allowing it rather than immediately trying to make it stop. Notice what happens to the sensation when it is not fought. This is a gradual practice and should start small, building only as tolerance grows.', '[{"id": "f0", "type": "textarea", "label": "The sensation I practiced allowing"}, {"id": "f1", "type": "textarea", "label": "How intense it felt at first"}, {"id": "f2", "type": "textarea", "label": "What happened when I stopped fighting it"}, {"id": "f3", "type": "textarea", "label": "How intense it felt after a minute of allowing it"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the urge to fight it"}]'::jsonb, array['panic attacks', 'core ACT', 'willingness']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('in-the-moment-panic-skills-card', 'In-the-Moment Panic Skills Card', 'dbt'::resource_kind, 'A pocket card of skills to use the moment panic starts to build, before it peaks.', 'Give the client a fast, ordered set of skills to reach for the moment panic starts.', array['Adults', 'Teens']::text[], 'Five minutes per use', 'List three or four skills in the order the client will actually try them, a paced breath count, a cold sensation, naming five things seen, so there is no decision-making required in the moment itself. Keep the card somewhere always reachable. If panic ever escalates toward thoughts of self-harm, that is addressed directly in session, and 988 (call or text) is named on the card as an option.', '[{"id": "f0", "type": "textarea", "label": "Skill one I will try first"}, {"id": "f1", "type": "textarea", "label": "Skill two if the first does not help"}, {"id": "f2", "type": "textarea", "label": "Skill three"}, {"id": "f3", "type": "textarea", "label": "Where I will keep this card"}, {"id": "f4", "type": "textarea", "label": "If thoughts of self-harm show up, what I will do (988, call or text)"}]'::jsonb, array['panic attacks', 'distress tolerance', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-panic-response-script', 'Partner Panic Response Script', 'couples'::resource_kind, 'Scripts a calm, specific response a partner can use when the client is having a panic episode.', 'Give a supporting partner a rehearsed, steady response instead of an improvised one under pressure.', array['Couples']::text[], '20 minutes', 'Ask the client what actually helps during a panic episode, a steady voice, a specific phrase, quiet presence without questions, and have the supporting partner rehearse exactly that response rather than guessing in the moment. Rehearse it together outside of an actual episode so it feels familiar when it is needed. Revisit and adjust the script after it gets used for real.', '[{"id": "f0", "type": "textarea", "label": "What actually helps me during an episode"}, {"id": "f1", "type": "textarea", "label": "What tends to make it worse"}, {"id": "f2", "type": "textarea", "label": "The exact words or actions my partner will use"}, {"id": "f3", "type": "textarea", "label": "How rehearsing this felt"}, {"id": "f4", "type": "textarea", "label": "How the script worked during a real episode"}]'::jsonb, array['panic attacks', 'support', 'couples']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('connection-before-correction-craft', 'Connection Before Correction Craft', 'kids'::resource_kind, 'A parent and child build a simple token board that gets a connection moment logged before any correction talk.', 'Help a parent build the habit of connecting with a child before addressing behavior.', array['Children', 'Adults']::text[], '20 minutes', 'The parent and child decorate a small board together, and the parent commits to logging one genuine connection moment, a hug, a shared joke, a few minutes of full attention, before bringing up any behavior that needs correcting that day. The child helps track the moments, which makes the habit visible for both of them. Review together at the end of the week.', '[{"id": "f0", "type": "textarea", "label": "A connection moment from today"}, {"id": "f1", "type": "textarea", "label": "How it felt to do the connection moment first"}, {"id": "f2", "type": "textarea", "label": "What correction talk followed, if any"}, {"id": "f3", "type": "textarea", "label": "How that conversation went compared to usual"}]'::jsonb, array['parenting', 'children', 'connection']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('what-would-a-calm-parent-say-game', 'What Would a Calm Parent Say Game', 'game'::resource_kind, 'Parents role-play common flashpoint scenes and try out a calmer response before it is needed for real.', 'Rehearse a calmer response to common flashpoints in a low-stakes practice setting.', array['Adults', 'Groups']::text[], '20 minutes', 'Read out common flashpoint scenes, a meltdown in a store, a refused bedtime, and have parents take turns responding out loud as the calm version of themselves before discussing what actually felt hard about it. Practicing the words out loud in a low-stakes setting makes them more available under real pressure. Close by picking one scene most likely to come up this week.', '[{"id": "f0", "type": "textarea", "label": "A scene I practiced responding to"}, {"id": "f1", "type": "textarea", "label": "What my calm response was"}, {"id": "f2", "type": "textarea", "label": "What made it hard to say"}, {"id": "f3", "type": "textarea", "label": "The scene most likely to come up for me this week"}, {"id": "f4", "type": "textarea", "label": "How I want to respond when it does"}]'::jsonb, array['parenting', 'group', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('household-routine-reset-sheet', 'Household Routine Reset Sheet', 'worksheet'::resource_kind, 'Rebuilds a strained daily routine, morning or bedtime, one predictable step at a time.', 'Give a family a clear, shared routine to fall back on when a transition keeps going badly.', array['Adults']::text[], '20 minutes', 'Have the parent map the routine as it currently, often chaotically, runs, then rebuild it step by step with realistic timing and one clear job for each family member. Post the new routine somewhere visible for the first couple of weeks while it becomes automatic. Revisit anything that keeps breaking down rather than assuming the whole routine has failed.', '[{"id": "f0", "type": "textarea", "label": "The routine as it currently runs"}, {"id": "f1", "type": "textarea", "label": "Where it tends to break down"}, {"id": "f2", "type": "textarea", "label": "The rebuilt step-by-step version"}, {"id": "f3", "type": "textarea", "label": "Each person''s job in the new routine"}, {"id": "f4", "type": "textarea", "label": "How the first week went"}]'::jsonb, array['parenting', 'routines']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('parent-reactivity-pause-sheet', 'Parent Reactivity Pause Sheet', 'cbt'::resource_kind, 'Identifies a parent''s personal triggers for reactive responses and plans a pause before responding.', 'Give a parent a specific pause to use before a triggered reaction takes over.', array['Adults']::text[], '20 minutes', 'Have the parent identify a couple of specific child behaviors that reliably trigger a reactive response, then plan an exact pause, a breath count, stepping back for a moment, to use before responding rather than after reacting. Rehearsing the pause when calm makes it more available when triggered. Track how often the pause actually got used and what happened when it did.', '[{"id": "f0", "type": "textarea", "label": "A behavior that reliably triggers me"}, {"id": "f1", "type": "textarea", "label": "What my reaction usually looks like"}, {"id": "f2", "type": "textarea", "label": "The pause I will use instead"}, {"id": "f3", "type": "textarea", "label": "How often I used the pause this week"}, {"id": "f4", "type": "textarea", "label": "What happened when I did"}]'::jsonb, array['parenting', 'core CBT', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('values-based-parenting-compass', 'Values-Based Parenting Compass', 'act'::resource_kind, 'Clarifies what kind of parent the client wants to be, separate from any single day''s performance.', 'Anchor parenting choices to values instead of to guilt over any one hard day.', array['Adults']::text[], '25 minutes', 'Ask the client to describe the kind of parent they want to be in a few words, patient, present, honest, and then compare a recent hard day against that description without treating the gap as proof of failure. Every day offers a fresh chance to move toward the compass direction. Use this as an ongoing touchstone rather than a one-time exercise.', '[{"id": "f0", "type": "textarea", "label": "Words that describe the parent I want to be"}, {"id": "f1", "type": "textarea", "label": "A recent day compared to that description"}, {"id": "f2", "type": "textarea", "label": "What got in the way that day"}, {"id": "f3", "type": "textarea", "label": "One small way to move toward the compass tomorrow"}, {"id": "f4", "type": "textarea", "label": "How I want to treat myself about the gap"}]'::jsonb, array['parenting', 'core ACT', 'values']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('postpartum-vulnerability-factors-check', 'Postpartum Vulnerability Factors Check', 'dbt'::resource_kind, 'Tracks sleep, eating and support for a new parent to explain a hard day without judgment.', 'Give a new parent a nonjudgmental explanation for why some days feel so much harder.', array['Adults']::text[], 'Five minutes daily', 'New-parent sleep and eating are often severely disrupted, and this daily check simply logs hours of sleep, whether a real meal happened, and whether any support showed up, without asking for anything more. A hard day next to a rough vulnerability profile reads very differently than a hard day next to a well-supported one. Use the pattern to plan where support is most needed.', '[{"id": "f0", "type": "textarea", "label": "Hours of sleep, even broken up"}, {"id": "f1", "type": "textarea", "label": "Did a real meal happen today"}, {"id": "f2", "type": "textarea", "label": "Support that showed up today"}, {"id": "f3", "type": "textarea", "label": "How today felt overall"}, {"id": "f4", "type": "textarea", "label": "What tomorrow''s support could look like"}]'::jsonb, array['perinatal and postpartum', 'self-monitoring', 'regulation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('new-parent-division-of-night-care-sheet', 'New Parent Division of Night Care Sheet', 'couples'::resource_kind, 'Maps out a fair, explicit plan for splitting night wakings and early mornings between partners.', 'Replace an assumed, unequal night-care arrangement with one both partners agreed to.', array['Couples']::text[], '20 minutes', 'Night care often defaults to whoever is around or whoever is breastfeeding, without either partner explicitly agreeing to the split, which breeds resentment over time. Map out the actual current split, then negotiate a version that accounts for both partners'' work schedules and recovery needs. Revisit as the baby''s patterns change, since what worked in week two rarely still fits at three months.', '[{"id": "f0", "type": "textarea", "label": "Partner A: night care as it currently runs"}, {"id": "f1", "type": "textarea", "label": "Partner B: night care as it currently runs"}, {"id": "f2", "type": "textarea", "label": "What feels unfair about the current split"}, {"id": "f3", "type": "textarea", "label": "The renegotiated plan"}, {"id": "f4", "type": "textarea", "label": "When we will revisit this plan"}]'::jsonb, array['perinatal and postpartum', 'couples', 'support']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('identity-beyond-new-parent-practice', 'Identity Beyond New Parent Practice', 'act'::resource_kind, 'Names parts of the client''s identity from before the baby and finds a small way to keep one alive.', 'Keep a thread of the client''s broader identity present during an intense season of new parenthood.', array['Adults']::text[], '20 minutes', 'New parenthood can swallow every other part of identity for a while, and this simply asks the client to name a few things that mattered before the baby, work, a hobby, a friendship, and pick one to keep even a small trace of alive right now. The goal is not balance, which is often unrealistic in this season, but not disappearing entirely. Revisit as things settle.', '[{"id": "f0", "type": "textarea", "label": "Parts of who I was before the baby"}, {"id": "f1", "type": "textarea", "label": "How much room they have right now"}, {"id": "f2", "type": "textarea", "label": "One I want to keep even a small trace of"}, {"id": "f3", "type": "textarea", "label": "What a small trace could look like this week"}, {"id": "f4", "type": "textarea", "label": "How it felt to do it"}]'::jsonb, array['perinatal and postpartum', 'core ACT', 'values']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('ask-for-help-roulette', 'Ask for Help Roulette', 'game'::resource_kind, 'A spinner of small, specific asks helps a new parent practice requesting support out loud.', 'Build the habit of asking for concrete help instead of waiting to be offered it.', array['Adults', 'Groups']::text[], '15 minutes', 'New parents often struggle to ask for help even when it is available, so this spinner lands on a specific, small ask, a meal, an hour of childcare, a load of laundry, and the client practices saying it out loud in session before trying it for real. Saying the words in a low-stakes setting first makes them easier to say when it counts. Debrief what made asking hard.', '[{"id": "f0", "type": "textarea", "label": "The ask the spinner landed on"}, {"id": "f1", "type": "textarea", "label": "How it felt to say it out loud"}, {"id": "f2", "type": "textarea", "label": "Who I could actually ask this week"}, {"id": "f3", "type": "textarea", "label": "What makes asking for help hard for me"}, {"id": "f4", "type": "textarea", "label": "How it went when I actually asked"}]'::jsonb, array['perinatal and postpartum', 'group', 'support']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('postpartum-mood-tracking-sheet', 'Postpartum Mood Tracking Sheet', 'worksheet'::resource_kind, 'Tracks daily mood, worry and bonding feelings across the early postpartum weeks in one simple grid.', 'Give the clinician and client a shared, simple record of how the early weeks are actually going.', array['Adults']::text[], 'Five minutes daily', 'A brief daily grid, rating mood, worry level and how connected the parent feels to the baby, builds a picture over weeks that any single conversation cannot capture, since a single hard day can look very different from a hard stretch. Bring the sheet to each session rather than relying on memory of how the week went. Flag any sharp or sustained dip for a closer look together.', '[{"id": "f0", "type": "textarea", "label": "Mood rating today (low to high)"}, {"id": "f1", "type": "textarea", "label": "Worry level today"}, {"id": "f2", "type": "textarea", "label": "How connected I felt to the baby today"}, {"id": "f3", "type": "textarea", "label": "Anything unusual about today"}, {"id": "f4", "type": "textarea", "label": "What I need more of this week"}]'::jsonb, array['perinatal and postpartum', 'monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('self-worth-conditions-audit', 'Self-Worth Conditions Audit', 'cbt'::resource_kind, 'Lists the unwritten conditions a client''s sense of worth currently depends on.', 'Surface the hidden conditions attached to feeling worthy, so they can be loosened.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients hold an unstated equation, worth equals achievement, worth equals being liked by everyone, without ever having examined it. Have the client list every condition their sense of worth currently seems to depend on, then rate how much control they actually have over each one. Conditions outside the client''s control are often the most worth challenging first.', '[{"id": "f0", "type": "textarea", "label": "A condition my worth seems to depend on"}, {"id": "f1", "type": "textarea", "label": "Another one"}, {"id": "f2", "type": "textarea", "label": "A third one"}, {"id": "f3", "type": "textarea", "label": "How much control I actually have over each"}, {"id": "f4", "type": "textarea", "label": "One condition I want to loosen first"}]'::jsonb, array['self-esteem', 'core beliefs', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('self-as-whole-person-practice', 'Self as Whole Person Practice', 'act'::resource_kind, 'Practices holding a full, mixed self-description instead of one dominated by a single flaw or failure.', 'Widen a narrow, harsh self-story into one that holds the client''s actual complexity.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client write a description of themselves that includes strengths, flaws, ordinary traits and recent struggles side by side, resisting the pull to let one item define the whole thing. Read it back and notice how different it feels from the usual single-flaw story running in the background. This works well as a repeatable practice, not a one-time list.', '[{"id": "f0", "type": "textarea", "label": "A strength I have"}, {"id": "f1", "type": "textarea", "label": "A flaw or struggle I have"}, {"id": "f2", "type": "textarea", "label": "Something ordinary and neutral about me"}, {"id": "f3", "type": "textarea", "label": "How it feels to hold all of these at once"}, {"id": "f4", "type": "textarea", "label": "Which single story I usually let define me instead"}]'::jsonb, array['self-esteem', 'core ACT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('self-validation-practice-card', 'Self-Validation Practice Card', 'dbt'::resource_kind, 'Practices validating one''s own reaction as understandable before deciding whether to change it.', 'Build the skill of validating a reaction as making sense, separate from judging it as good or bad.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client pick a recent reaction they judged themselves harshly for, and practice a two-step move: first state why the reaction made sense given the situation, then separately decide whether anything about the response needs to change. Skipping the validation step and going straight to judgment is the pattern this interrupts. Practice on a few different reactions across the week.', '[{"id": "f0", "type": "textarea", "label": "A reaction I judged myself for"}, {"id": "f1", "type": "textarea", "label": "Why that reaction actually made sense"}, {"id": "f2", "type": "textarea", "label": "Whether anything about my response still needs to change"}, {"id": "f3", "type": "textarea", "label": "How it felt to validate before judging"}, {"id": "f4", "type": "textarea", "label": "Another reaction to try this with"}]'::jsonb, array['self-esteem', 'regulation', 'self-compassion']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-reflected-strengths-exchange', 'Partner Reflected Strengths Exchange', 'couples'::resource_kind, 'Partners write down strengths they see in each other that the other person tends to overlook in themselves.', 'Use a trusted partner''s outside view to counter a client''s own harsh self-view.', array['Couples']::text[], '20 minutes', 'Each partner privately lists strengths they see in the other, especially ones they suspect the other person does not fully see in themselves, then reads the list aloud. Being told a specific, observed strength by someone who knows the client well often lands harder than a general compliment. Keep the lists somewhere they can be revisited on a hard day.', '[{"id": "f0", "type": "textarea", "label": "Partner A: strengths I see in you"}, {"id": "f1", "type": "textarea", "label": "Partner A: which one I think you underrate"}, {"id": "f2", "type": "textarea", "label": "Partner B: strengths I see in you"}, {"id": "f3", "type": "textarea", "label": "Partner B: which one I think you underrate"}, {"id": "f4", "type": "textarea", "label": "How it felt to hear this list"}]'::jsonb, array['self-esteem', 'couples', 'Gottman']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('strength-collector-sticker-chart', 'Strength Collector Sticker Chart', 'kids'::resource_kind, 'A child collects a sticker each time they notice themselves doing something they are proud of.', 'Help a child build a running, visible record of their own strengths and efforts.', array['Children']::text[], 'One week', 'The parent helps the child add a sticker to a chart any time the child notices, with the parent''s help at first, a moment of trying hard, being kind, or doing something well, and names it out loud together. Reviewing the growing chart at the end of the week gives the child a visible collection of evidence rather than a vague sense of doing okay. Let the child pick the sticker theme.', '[{"id": "f0", "type": "textarea", "label": "A sticker moment from today"}, {"id": "f1", "type": "textarea", "label": "What I did that earned it"}, {"id": "f2", "type": "textarea", "label": "How it felt to notice it"}, {"id": "f3", "type": "textarea", "label": "My favorite sticker moment from the whole week"}]'::jsonb, array['self-esteem', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('conversation-starter-draw-game', 'Conversation Starter Draw Game', 'game'::resource_kind, 'Players draw conversation-starter cards and practice using them in a low-stakes round-robin.', 'Build comfort with initiating conversation through repeated, low-stakes practice.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Shuffle a deck of simple conversation-starter cards and have players take turns drawing one and using it to start a brief exchange with another player. Repetition in a safe setting builds familiarity with the mechanics of starting a conversation, which is often the hardest part. Debrief which starters felt most natural and which felt forced.', '[{"id": "f0", "type": "textarea", "label": "A starter that felt natural to use"}, {"id": "f1", "type": "textarea", "label": "One that felt forced"}, {"id": "f2", "type": "textarea", "label": "How the exchange went"}, {"id": "f3", "type": "textarea", "label": "A starter I would actually use outside this room"}]'::jsonb, array['social anxiety', 'group', 'exposure']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('social-spotlight-effect-log', 'Social Spotlight Effect Log', 'worksheet'::resource_kind, 'Logs a client''s prediction of how much others noticed a perceived social mistake against the likely reality.', 'Challenge the sense that others are watching and judging as closely as it feels.', array['Adults', 'Teens']::text[], '15 minutes', 'After a social situation the client felt went badly, have them write their prediction of how much others noticed and judged it, then estimate honestly how much attention the client themselves pays to other people''s small stumbles. The comparison usually reveals a large gap between the felt spotlight and the likely reality. Repeat across several situations to build the pattern.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What I think others noticed"}, {"id": "f2", "type": "textarea", "label": "How much attention I actually pay to other people''s small mistakes"}, {"id": "f3", "type": "textarea", "label": "The likely gap between my prediction and reality"}, {"id": "f4", "type": "textarea", "label": "What I want to remember next time"}]'::jsonb, array['social anxiety', 'thinking traps', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('safety-behavior-drop-experiment', 'Safety Behavior Drop Experiment', 'cbt'::resource_kind, 'Tests dropping one small safety behavior in a social situation to see what actually happens.', 'Show the client that a safety behavior was not the thing preventing disaster.', array['Adults', 'Teens']::text[], 'One social situation', 'Have the client identify one small safety behavior, rehearsing lines in advance, avoiding eye contact, and plan to drop it in one specific, low-stakes social situation this week. Predict the outcome beforehand, then compare it to what actually happened. Dropping even one safety behavior and surviving it tends to do more than any amount of discussion about why it is unnecessary.', '[{"id": "f0", "type": "textarea", "label": "The safety behavior I will drop"}, {"id": "f1", "type": "textarea", "label": "The situation I will drop it in"}, {"id": "f2", "type": "textarea", "label": "My prediction beforehand"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What this tells me about the safety behavior"}]'::jsonb, array['social anxiety', 'core CBT', 'exposure']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('values-guided-social-approach-ladder', 'Values-Guided Social Approach Ladder', 'act'::resource_kind, 'Builds a graded ladder of social situations to approach, anchored to what the client actually wants from connection.', 'Use values as the reason to approach social situations, not the absence of anxiety.', array['Adults', 'Teens']::text[], 'Several weeks', 'Before building the exposure ladder itself, ask what the client actually wants from social connection, closer friendships, being known at work, and use that as the anchor for choosing which rungs matter most. Anxiety will likely be present at every rung, and that is treated as expected, not as a sign to stop. Track willingness to approach alongside anxiety level at each rung.', '[{"id": "f0", "type": "textarea", "label": "What I actually want from social connection"}, {"id": "f1", "type": "textarea", "label": "Rung one on my ladder"}, {"id": "f2", "type": "textarea", "label": "Rung two"}, {"id": "f3", "type": "textarea", "label": "Rung three"}, {"id": "f4", "type": "textarea", "label": "Anxiety level versus willingness at the last rung I tried"}]'::jsonb, array['social anxiety', 'core ACT', 'exposure']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('pre-event-skills-prep-card', 'Pre-Event Skills Prep Card', 'dbt'::resource_kind, 'A short pre-event routine of skills to use before a dreaded social event.', 'Give the client a rehearsed routine to lower the spike right before a social event.', array['Adults', 'Teens']::text[], '10 minutes before an event', 'List two or three skills the client will use in the minutes before a social event, a paced breath, a grounding phrase, a reminder of one value-based reason for going, so there is a rehearsed routine instead of a scramble in the moment. Practice the routine ahead of an actual event so it feels familiar. Log how the event went compared to the pre-event dread.', '[{"id": "f0", "type": "textarea", "label": "The event coming up"}, {"id": "f1", "type": "textarea", "label": "Skill one I will use beforehand"}, {"id": "f2", "type": "textarea", "label": "Skill two"}, {"id": "f3", "type": "textarea", "label": "My dread level before the event (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "How the event actually went"}]'::jsonb, array['social anxiety', 'regulation', 'skills']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('grieving-together-differently-sheet', 'Grieving Together Differently Sheet', 'couples'::resource_kind, 'Helps a couple name their different grieving styles so neither reads the other''s pace as not caring.', 'Prevent a couple''s different grieving styles from being misread as indifference or excess.', array['Couples']::text[], '25 minutes', 'Partners often grieve on different timelines and in different visible ways, one talking often, one going quiet, and without naming this explicitly, it can be misread as not caring or as being stuck. Have each partner describe their own style and what they need from the other during it. Revisit around anniversaries or other hard dates, when styles can shift again.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I tend to grieve"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need from you during it"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I tend to grieve"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need from you during it"}, {"id": "f4", "type": "textarea", "label": "A moment this month our styles clashed"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('memory-keepsake-box-craft', 'Memory Keepsake Box Craft', 'kids'::resource_kind, 'A child decorates a box and fills it with small items and drawings connected to someone or something lost.', 'Give a child a concrete, ongoing place to keep memories of a loss.', array['Children']::text[], '30 minutes', 'The parent and child decorate a small box together and add items over time, a photo, a drawing, a small object, connected to the person or pet who died. Opening the box together on hard days gives the child a way to stay connected to the memory rather than feeling like they have to avoid it. There is no wrong way to fill the box, and the child leads what goes in.', '[{"id": "f0", "type": "textarea", "label": "Something I put in my box today"}, {"id": "f1", "type": "textarea", "label": "Why I chose it"}, {"id": "f2", "type": "textarea", "label": "A memory it brings up"}, {"id": "f3", "type": "textarea", "label": "How I feel when I open the box"}]'::jsonb, array['grief and loss', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('grief-wave-weather-report-game', 'Grief Wave Weather Report Game', 'game'::resource_kind, 'Players give a short weather-style report on their grief that day, then compare reports over a few sessions.', 'Normalize grief''s unpredictable rise and fall through a repeatable, playful check-in.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'Each player gives a short weather report for their grief that day, stormy, partly cloudy, calm, and can add a brief reason if they want to. Repeating this over several sessions shows the group that grief moves in waves rather than a steady decline, which is often a relief to hear from peers rather than just from a clinician. Keep it brief and optional to elaborate.', '[{"id": "f0", "type": "textarea", "label": "My grief weather report today"}, {"id": "f1", "type": "textarea", "label": "What is behind today''s report, if I want to share"}, {"id": "f2", "type": "textarea", "label": "How my reports have changed over recent sessions"}, {"id": "f3", "type": "textarea", "label": "Something that helped on a stormy day"}]'::jsonb, array['grief and loss', 'group', 'psychoeducation']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('unfinished-conversations-letter', 'Unfinished Conversations Letter', 'worksheet'::resource_kind, 'Has the client write what they wish they had said to someone who died.', 'Give the client a place to say what was left unsaid.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client write directly to the person who died, saying whatever was left unsaid, an apology, a thank you, an update on life since. There is no right content and no expectation of sending or reading it aloud unless the client wants to. Some clients want to write more than one over time, and that is fine.', '[{"id": "f0", "type": "textarea", "label": "What I wish I had said"}, {"id": "f1", "type": "textarea", "label": "What I want them to know now"}, {"id": "f2", "type": "textarea", "label": "A memory I keep coming back to"}, {"id": "f3", "type": "textarea", "label": "What I want to do with this letter"}]'::jsonb, array['grief and loss', 'continuing bonds']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('grief-and-guilt-untangling-sheet', 'Grief and Guilt Untangling Sheet', 'cbt'::resource_kind, 'Separates genuine responsibility from guilt that has attached itself to a loss without real basis.', 'Sort what the client is actually responsible for from guilt that grief has generated on its own.', array['Adults']::text[], '25 minutes', 'Grief often pulls guilt along with it, including guilt about things the client had no real control over. Have the client list each guilty thought separately, then sort it into genuine responsibility versus grief-generated guilt, using the same evidence-weighing questions used for any other belief. This is slow, sensitive work and should not be rushed toward a tidy conclusion.', '[{"id": "f0", "type": "textarea", "label": "A guilty thought connected to the loss"}, {"id": "f1", "type": "textarea", "label": "The evidence I actually had control"}, {"id": "f2", "type": "textarea", "label": "The evidence I did not have control"}, {"id": "f3", "type": "textarea", "label": "Which category this thought falls into"}, {"id": "f4", "type": "textarea", "label": "What I want to do with this thought now"}]'::jsonb, array['grief and loss', 'core CBT', 'guilt']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('values-for-this-relationship-sheet', 'Values for This Relationship Sheet', 'act'::resource_kind, 'Clarifies what the client wants a specific relationship to stand for, separate from current conflict.', 'Reconnect a strained relationship to what the client actually wants it to be about.', array['Adults']::text[], '20 minutes', 'Ask the client to describe what they want this particular relationship to stand for, honesty, humor, reliability, independent of any current conflict, then compare that to how the relationship has actually been running lately. The gap is not evidence of failure but a direction to work toward. Pick one small action this week that moves toward the stated values.', '[{"id": "f0", "type": "textarea", "label": "What I want this relationship to stand for"}, {"id": "f1", "type": "textarea", "label": "How it has actually been running lately"}, {"id": "f2", "type": "textarea", "label": "The gap between the two"}, {"id": "f3", "type": "textarea", "label": "One small action toward the values this week"}, {"id": "f4", "type": "textarea", "label": "How that action went"}]'::jsonb, array['relationship issues', 'core ACT', 'values']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('relationship-distress-tolerance-plan', 'Relationship Distress Tolerance Plan', 'dbt'::resource_kind, 'Plans skills to use during an especially painful relationship moment without making it worse.', 'Give the client a way to get through an acute relationship low point without a reaction that compounds it.', array['Adults', 'Teens']::text[], '15 minutes', 'Painful relationship moments, a breakup conversation, a betrayal discovered, call for surviving the moment more than solving anything, so this plans specific skills, calling a support person, physical movement, a distraction that actually works, to use right then. Decide these in advance rather than in the moment itself. Revisit which skills actually helped afterward.', '[{"id": "f0", "type": "textarea", "label": "The kind of moment this plan is for"}, {"id": "f1", "type": "textarea", "label": "Skill one I will use"}, {"id": "f2", "type": "textarea", "label": "Skill two"}, {"id": "f3", "type": "textarea", "label": "A support person I can call"}, {"id": "f4", "type": "textarea", "label": "Which skills actually helped last time"}]'::jsonb, array['relationship issues', 'distress tolerance']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('attachment-needs-disclosure-sheet', 'Attachment Needs Disclosure Sheet', 'couples'::resource_kind, 'Has each partner name an underlying attachment need behind a recurring complaint.', 'Get past the surface complaint to the attachment need actually driving it.', array['Couples']::text[], '25 minutes', 'A recurring complaint, always working late, never initiating plans, often sits on top of a deeper need for reassurance, closeness or respect that never gets named directly. Have each partner trace one recurring complaint back to the need underneath it, then share the need rather than the complaint. This shift in language often changes the entire tone of the conversation that follows.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a recurring complaint"}, {"id": "f1", "type": "textarea", "label": "Partner A: the need underneath it"}, {"id": "f2", "type": "textarea", "label": "Partner B: a recurring complaint"}, {"id": "f3", "type": "textarea", "label": "Partner B: the need underneath it"}, {"id": "f4", "type": "textarea", "label": "How naming the need changed the conversation"}]'::jsonb, array['relationship issues', 'couples', 'attachment']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('family-feelings-weather-check-craft', 'Family Feelings Weather Check Craft', 'kids'::resource_kind, 'A child and parent each place a marker on a shared weather chart to show how the family feels that day.', 'Give a family a simple, visual way to check in about tension at home.', array['Children', 'Adults']::text[], '10 minutes daily', 'Each family member places a small marker on a shared sun-to-storm chart once a day, giving the family a quick, low-pressure way to notice tension building before it becomes a bigger issue. The child gets equal say in the chart, which itself communicates that their read on the household matters. Talk briefly about any storm markers, but do not force a full conversation if no one is ready.', '[{"id": "f0", "type": "textarea", "label": "Where I placed my marker today"}, {"id": "f1", "type": "textarea", "label": "What is behind my marker, if I want to share"}, {"id": "f2", "type": "textarea", "label": "Where other family members placed theirs"}, {"id": "f3", "type": "textarea", "label": "Something that could move the weather toward sun"}]'::jsonb, array['relationship issues', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('repair-attempt-recognition-game', 'Repair Attempt Recognition Game', 'game'::resource_kind, 'Partners practice spotting and rewarding each other''s small repair attempts during a mock disagreement.', 'Build a couple''s ability to notice and accept a repair attempt in real time.', array['Couples']::text[], '25 minutes', 'Have the couple act out a mild, scripted disagreement and practice inserting small repair attempts, a joke, a softer tone, reaching for a hand, then pause and name out loud when a repair attempt happened and whether it landed. Missed repair attempts are common and worth discussing without blame. Repeat with a slightly different scenario to build the recognition habit.', '[{"id": "f0", "type": "textarea", "label": "A repair attempt I made"}, {"id": "f1", "type": "textarea", "label": "Whether my partner caught it"}, {"id": "f2", "type": "textarea", "label": "A repair attempt my partner made"}, {"id": "f3", "type": "textarea", "label": "Whether I caught it"}, {"id": "f4", "type": "textarea", "label": "What made a repair attempt easier or harder to notice"}]'::jsonb, array['relationship issues', 'repair', 'Gottman']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('body-safety-and-choice-reclaiming-sheet', 'Body Safety and Choice Reclaiming Sheet', 'worksheet'::resource_kind, 'Lists small, everyday choices the client can make about their own body and space to rebuild a sense of control.', 'Rebuild a felt sense of choice and control over the client''s own body, in small everyday ways.', array['Adults']::text[], '20 minutes', 'List small, ordinary choices the client already has about their own body and personal space, what to wear, whether to hug someone hello, how close to sit to another person, and note which ones currently feel accessible versus which still feel hard to claim. This stays focused on present-day choice and control, never on recounting what happened. Build from the choices that already feel available.', '[{"id": "f0", "type": "textarea", "label": "A choice about my body that feels accessible right now"}, {"id": "f1", "type": "textarea", "label": "A choice that still feels hard to claim"}, {"id": "f2", "type": "textarea", "label": "What would help make it more accessible"}, {"id": "f3", "type": "textarea", "label": "One small choice I will practice claiming this week"}, {"id": "f4", "type": "textarea", "label": "How it felt to claim it"}]'::jsonb, array['sexual abuse', 'safety', 'coping skills']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('present-day-safety-evidence-log', 'Present-Day Safety Evidence Log', 'cbt'::resource_kind, 'Logs evidence from daily life that the client''s current environment is safe, to counter a persistent sense of danger.', 'Help the client''s nervous system gather evidence that today is not the same as the past.', array['Adults']::text[], 'One week', 'Each day, have the client note one piece of concrete evidence that their current environment and relationships are safe, a locked door, a trusted person nearby, a boundary that was respected. This builds a body of present-day evidence over time without ever asking the client to revisit or describe what happened previously. Review the accumulating log together in session.', '[{"id": "f0", "type": "textarea", "label": "Today''s evidence of safety"}, {"id": "f1", "type": "textarea", "label": "How much my body believed it, out of ten"}, {"id": "f2", "type": "textarea", "label": "What helped it land, if anything"}, {"id": "f3", "type": "textarea", "label": "What I want to notice more of this week"}]'::jsonb, array['sexual abuse', 'safety', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('self-compassion-for-the-younger-self-practice', 'Self-Compassion for the Younger Self Practice', 'act'::resource_kind, 'Practices directing compassion toward a younger version of the client who went through a hard experience.', 'Offer the client''s present self a way to extend compassion to a younger self, without revisiting details.', array['Adults']::text[], '20 minutes', 'Ask the client to picture a younger version of themselves and write what they would want that younger self to know now, without describing what happened to them. Keep the focus entirely on comfort and compassion directed at the younger self, not on narrating events. Some clients find this easier through drawing or a photo rather than direct visualization; either is fine.', '[{"id": "f0", "type": "textarea", "label": "What I would want my younger self to know"}, {"id": "f1", "type": "textarea", "label": "How I would want to comfort them"}, {"id": "f2", "type": "textarea", "label": "What I notice in my body doing this practice"}, {"id": "f3", "type": "textarea", "label": "What my present self needs to hear too"}]'::jsonb, array['sexual abuse', 'self-compassion', 'core ACT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('grounding-through-the-body-practice', 'Grounding Through the Body Practice', 'dbt'::resource_kind, 'A body-based grounding sequence for use when a client feels pulled out of the present moment.', 'Give the client a reliable, body-based way back to the present when it starts to slip.', array['Adults', 'Teens']::text[], '10 minutes', 'Walk through pressing feet into the floor, naming the temperature of the air, and noticing a point of contact with a chair or the ground, slowly and in session first. This is a stabilizing skill and is not paired with any request to recall or narrate past events. If the practice ever brings up thoughts of self-harm, pause and address it directly in session, with 988 (call or text) available right away.', '[{"id": "f0", "type": "textarea", "label": "What I feel pressing into the floor"}, {"id": "f1", "type": "textarea", "label": "The temperature of the air around me"}, {"id": "f2", "type": "textarea", "label": "A point of contact I can notice"}, {"id": "f3", "type": "textarea", "label": "How grounded I feel now compared to before (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "If thoughts of self-harm come up, what I will do (988, call or text)"}]'::jsonb, array['sexual abuse', 'grounding', 'distress tolerance']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('supporting-a-partner-who-is-a-survivor-sheet', 'Supporting a Partner Who Is a Survivor Sheet', 'couples'::resource_kind, 'Helps the non-survivor partner learn what supportive, non-pressuring responses look like day to day.', 'Give a supporting partner concrete, low-pressure ways to be helpful without pushing for more than the survivor is ready for.', array['Couples']::text[], '25 minutes', 'The supporting partner often wants to help but is unsure what is welcome, so this has the survivor name what support currently feels good, patience with physical closeness, not asking questions, checking in without pressure, while the supporting partner names their own questions or worries separately. Keep the focus on present-day support needs, not on discussing what happened. Revisit as needs shift over time.', '[{"id": "f0", "type": "textarea", "label": "Survivor: what support feels good right now"}, {"id": "f1", "type": "textarea", "label": "Survivor: what does not feel good right now"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: a worry I have about getting this right"}, {"id": "f3", "type": "textarea", "label": "Supporting partner: what I will try instead"}, {"id": "f4", "type": "textarea", "label": "How this conversation felt for each of us"}]'::jsonb, array['sexual abuse', 'support', 'couples']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('coping-toolbox-craft', 'Coping Toolbox Craft', 'kids'::resource_kind, 'A child decorates a small box and fills it with reminders of coping skills that actually work for them.', 'Give a child a physical, personalized collection of their own working coping skills.', array['Children']::text[], '25 minutes', 'The parent and child decorate a small box together, then fill it with cards or small objects representing coping skills that have actually worked before, a stress ball, a breathing card, a photo of a calming place. The child picks what goes in based on their own experience, not a generic list. Keep the box somewhere easy to reach during a hard moment.', '[{"id": "f0", "type": "textarea", "label": "A coping skill I put in my box"}, {"id": "f1", "type": "textarea", "label": "Why I picked it"}, {"id": "f2", "type": "textarea", "label": "Another skill I added"}, {"id": "f3", "type": "textarea", "label": "A time this week I used something from my box"}]'::jsonb, array['coping skills', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('coping-skill-speed-match-game', 'Coping Skill Speed Match Game', 'game'::resource_kind, 'Players race to match a distressing scenario card with the coping skill card that fits it best.', 'Build quick recall of which coping skill fits which kind of distress.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Lay out scenario cards and coping skill cards, then have players race, individually or in teams, to make the fastest correct matches, discussing any disputed pairing afterward since more than one skill can often fit. This builds quick recall under a bit of pressure, closer to how skill use actually needs to work in real moments. Close by asking each player their go-to match.', '[{"id": "f0", "type": "textarea", "label": "A match I made quickly"}, {"id": "f1", "type": "textarea", "label": "A match that was disputed"}, {"id": "f2", "type": "textarea", "label": "My personal go-to skill for a tough scenario"}, {"id": "f3", "type": "textarea", "label": "A skill I want to get better at reaching for"}]'::jsonb, array['coping skills', 'group']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('coping-skill-context-map', 'Coping Skill Context Map', 'worksheet'::resource_kind, 'Sorts a client''s coping skills by the setting they are actually usable in, home, work, in public.', 'Match coping skills to where the client can realistically use them, not just what sounds good on paper.', array['Adults', 'Teens']::text[], '20 minutes', 'A coping skill that works well at home may be impossible to use discreetly at work, so this sorts the client''s known skills by setting: private and unlimited, at work, in public, in front of others. Identify any setting with no usable skill yet and brainstorm one that would actually fit there. This turns a general coping list into something usable in the moment it is actually needed.', '[{"id": "f0", "type": "textarea", "label": "Skills that work at home"}, {"id": "f1", "type": "textarea", "label": "Skills that work at work or school"}, {"id": "f2", "type": "textarea", "label": "Skills that work in public"}, {"id": "f3", "type": "textarea", "label": "A setting with no skill yet"}, {"id": "f4", "type": "textarea", "label": "A skill to try building for that setting"}]'::jsonb, array['coping skills', 'self-monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('coping-skill-cost-and-payoff-sheet', 'Coping Skill Cost and Payoff Sheet', 'cbt'::resource_kind, 'Weighs the short-term relief and longer-term cost of a client''s current coping habits.', 'Help the client see which coping habits are worth keeping and which are worth replacing.', array['Adults', 'Teens']::text[], '20 minutes', 'List the client''s current go-to coping habits, healthy and less healthy alike, and rate each for short-term relief and longer-term cost side by side. Some habits will score well on both, some will trade a small relief for a larger cost, and naming that plainly makes the tradeoff visible without moralizing about it. Pick one habit to work on shifting first.', '[{"id": "f0", "type": "textarea", "label": "A current coping habit"}, {"id": "f1", "type": "textarea", "label": "Short-term relief it provides"}, {"id": "f2", "type": "textarea", "label": "Longer-term cost, if any"}, {"id": "f3", "type": "textarea", "label": "Another habit and the same rating"}, {"id": "f4", "type": "textarea", "label": "Which habit I want to shift first"}]'::jsonb, array['coping skills', 'core CBT', 'self-monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('values-matched-coping-menu', 'Values-Matched Coping Menu', 'act'::resource_kind, 'Builds a coping skills menu filtered through which ones actually fit the client''s values, not just what is calming.', 'Choose coping skills that both soothe and align with the kind of life the client wants to build.', array['Adults', 'Teens']::text[], '20 minutes', 'Rather than listing coping skills purely by how calming they are, have the client also rate how well each one fits the life they are trying to build, a skill that isolates the client from people who matter might soothe short term while working against a value of connection. Keep the ones that score well on both. This produces a shorter, more genuinely useful menu than a generic list.', '[{"id": "f0", "type": "textarea", "label": "A coping skill and how calming it is"}, {"id": "f1", "type": "textarea", "label": "How well it fits my values"}, {"id": "f2", "type": "textarea", "label": "Another skill and the same two ratings"}, {"id": "f3", "type": "textarea", "label": "A skill that scores well on both"}, {"id": "f4", "type": "textarea", "label": "A skill I might want to swap out"}]'::jsonb, array['coping skills', 'core ACT', 'values']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('phobia-exposure-distress-tolerance-card', 'Phobia Exposure Distress Tolerance Card', 'dbt'::resource_kind, 'A skills card to use during a planned exposure to a feared object or situation.', 'Give the client skills to stay with a planned exposure step instead of escaping it.', array['Adults', 'Teens']::text[], '10 minutes per use', 'List two or three skills the client will use to stay present during a planned exposure step, paced breathing, a grounding phrase, reminding themselves the goal is staying rather than feeling calm. Rehearse the card before the actual exposure happens. Log distress at the start, peak and end of the step to show the client their own pattern of the fear settling over time.', '[{"id": "f0", "type": "textarea", "label": "The exposure step planned"}, {"id": "f1", "type": "textarea", "label": "Skill I will use to stay with it"}, {"id": "f2", "type": "textarea", "label": "Distress at the start"}, {"id": "f3", "type": "textarea", "label": "Distress at the peak"}, {"id": "f4", "type": "textarea", "label": "Distress at the end"}]'::jsonb, array['phobias', 'exposure', 'distress tolerance']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-support-during-exposure-sheet', 'Partner Support During Exposure Sheet', 'couples'::resource_kind, 'Defines exactly how a partner can help during a planned exposure without accidentally rescuing.', 'Keep a well-meaning partner''s support from turning into an escape route during exposure work.', array['Couples']::text[], '20 minutes', 'A supporting partner''s instinct to comfort can accidentally let the client escape the exposure early, so this spells out exactly what helpful support looks like, staying nearby, not offering an out, a specific phrase of encouragement, versus what to avoid. Both partners agree on the plan together before the exposure happens. Debrief afterward on what actually helped.', '[{"id": "f0", "type": "textarea", "label": "Client: what support helps during exposure"}, {"id": "f1", "type": "textarea", "label": "Client: what accidentally lets me escape"}, {"id": "f2", "type": "textarea", "label": "Partner: what I will say or do"}, {"id": "f3", "type": "textarea", "label": "Partner: what I will avoid doing"}, {"id": "f4", "type": "textarea", "label": "How the last exposure went with this plan"}]'::jsonb, array['phobias', 'couples', 'exposure']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('brave-steps-feared-thing-chart', 'Brave Steps Feared Thing Chart', 'kids'::resource_kind, 'A child builds a step-by-step chart toward a feared object or situation, adding a sticker at each step.', 'Give a child a visible, gradual path toward a feared thing instead of an all-or-nothing leap.', array['Children']::text[], 'One to two weeks', 'The parent and child break a feared thing, a dog, the dark, a doctor visit, into small steps and build a chart together, adding a sticker each time a step is managed. The parent stays close and matches the pace to the child rather than pushing to the next step before the current one feels steady. Celebrate every step, including ones that need repeating.', '[{"id": "f0", "type": "textarea", "label": "The feared thing on my chart"}, {"id": "f1", "type": "textarea", "label": "The step I am working on"}, {"id": "f2", "type": "textarea", "label": "How scared I felt (small, medium, big)"}, {"id": "f3", "type": "textarea", "label": "The sticker I earned"}, {"id": "f4", "type": "textarea", "label": "The next step on my chart"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('fear-fact-check-game', 'Fear Fact Check Game', 'game'::resource_kind, 'Players sort statements about a feared object into facts and fear-driven exaggerations.', 'Separate the real facts about a feared object from what fear has exaggerated.', array['Teens', 'Groups']::text[], '20 minutes', 'Prepare a set of statements about a commonly feared object or situation, some accurate and some exaggerated by fear, and have players sort them while discussing why fear tends to distort in that particular direction. This works especially well in a group where members share the same or different phobias. Close with each player''s own fear-driven exaggeration and its more accurate counterpart.', '[{"id": "f0", "type": "textarea", "label": "A statement I correctly sorted as fact"}, {"id": "f1", "type": "textarea", "label": "A statement I correctly sorted as exaggeration"}, {"id": "f2", "type": "textarea", "label": "My own fear-driven exaggeration about my feared thing"}, {"id": "f3", "type": "textarea", "label": "A more accurate version of that same statement"}]'::jsonb, array['phobias', 'group', 'thinking traps']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('fear-hierarchy-refresh-sheet', 'Fear Hierarchy Refresh Sheet', 'worksheet'::resource_kind, 'Revisits and updates an existing exposure hierarchy as steps become easier or new ones become relevant.', 'Keep a fear hierarchy current instead of letting it go stale as progress happens.', array['Adults', 'Teens']::text[], '20 minutes', 'A hierarchy built weeks ago often no longer matches where the client actually is, so this has the client re-rate each step''s current distress level and add any new steps that have become relevant since. Steps that have dropped in distress can be marked complete, and steps that never got attempted can be reconsidered. This keeps exposure work matched to real, current progress.', '[{"id": "f0", "type": "textarea", "label": "A step whose distress rating has changed"}, {"id": "f1", "type": "textarea", "label": "New distress rating for it"}, {"id": "f2", "type": "textarea", "label": "A step I have not attempted yet"}, {"id": "f3", "type": "textarea", "label": "A new step to add to the hierarchy"}, {"id": "f4", "type": "textarea", "label": "The next step to work on"}]'::jsonb, array['phobias', 'exposure', 'monitoring']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('appearance-talk-reduction-log', 'Appearance Talk Reduction Log', 'cbt'::resource_kind, 'Tracks how often a client''s day involves appearance-focused talk or thought, without judgment.', 'Build awareness of how much daily attention appearance talk is actually taking up.', array['Adults', 'Teens']::text[], 'One week', 'Have the client note, without judging the count, every time appearance came up in their own thinking or in conversation with others across a day. Awareness alone often starts to shift the habit before any active change is asked for. Use the log to spot one specific moment or conversation pattern worth working on directly.', '[{"id": "f0", "type": "textarea", "label": "A moment appearance came up in my thinking today"}, {"id": "f1", "type": "textarea", "label": "A moment it came up in conversation"}, {"id": "f2", "type": "textarea", "label": "How many times total, roughly"}, {"id": "f3", "type": "textarea", "label": "A pattern I noticed across the week"}, {"id": "f4", "type": "textarea", "label": "One moment I want to work on changing"}]'::jsonb, array['body image', 'self-monitoring', 'core CBT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('body-as-instrument-practice', 'Body as Instrument Practice', 'act'::resource_kind, 'Practices describing the body by what it does and enables rather than by how it looks.', 'Shift attention from appearance to function as a different, workable relationship with the body.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client list what their body actually lets them do across a typical day, carrying groceries, hugging someone, walking somewhere they wanted to go, without any reference to appearance. This is a genuine shift in attention, not a trick to force positivity, and some days will feel easier than others. Revisit the list regularly rather than writing it once.', '[{"id": "f0", "type": "textarea", "label": "Something my body let me do today"}, {"id": "f1", "type": "textarea", "label": "Another thing"}, {"id": "f2", "type": "textarea", "label": "A way my body has supported me over the years"}, {"id": "f3", "type": "textarea", "label": "How it felt to describe my body this way"}, {"id": "f4", "type": "textarea", "label": "What I want to notice more of tomorrow"}]'::jsonb, array['body image', 'core ACT']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('mirror-time-limit-practice', 'Mirror Time Limit Practice', 'dbt'::resource_kind, 'Practices a brief, timed mirror check paired with a grounding skill instead of an open-ended one.', 'Interrupt a pattern of extended mirror-checking with a bounded, skills-paired alternative.', array['Adults', 'Teens']::text[], 'One week', 'Extended mirror-checking often increases distress rather than resolving it, so this sets a short time limit for any mirror check, thirty seconds works for many clients, followed immediately by a grounding or self-soothing skill. Log how often the urge to check longer showed up and how the paired skill affected it. This is a gradual practice and does not need to be perfect from day one.', '[{"id": "f0", "type": "textarea", "label": "A mirror check today and how long it lasted"}, {"id": "f1", "type": "textarea", "label": "The skill I paired with it"}, {"id": "f2", "type": "textarea", "label": "The urge to check longer, rated 0 to 10"}, {"id": "f3", "type": "textarea", "label": "How I felt right after using the skill"}, {"id": "f4", "type": "textarea", "label": "What I noticed by the end of the week"}]'::jsonb, array['body image', 'distress tolerance']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('partner-appearance-comment-agreement', 'Partner Appearance Comment Agreement', 'couples'::resource_kind, 'Has a couple agree on how appearance gets talked about, or not, between them.', 'Give a couple a shared, explicit agreement about appearance comments instead of leaving it unspoken.', array['Couples']::text[], '20 minutes', 'Well-meaning appearance comments, even compliments, can land badly for a partner working on their body image, so this has both partners name what kind of comments actually help, what kind do not, and agree on an alternative way to express care that does not center appearance at all. Revisit if either partner notices the agreement slipping. Keep the tone collaborative rather than restrictive.', '[{"id": "f0", "type": "textarea", "label": "Partner A: appearance comments that help"}, {"id": "f1", "type": "textarea", "label": "Partner A: appearance comments that do not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: appearance comments that help"}, {"id": "f3", "type": "textarea", "label": "Partner B: appearance comments that do not help"}, {"id": "f4", "type": "textarea", "label": "A non-appearance way we will express care instead"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-09-25T15:00:00+00:00'::timestamptz),
  ('bodies-do-many-things-drawing', 'Bodies Do Many Things Drawing', 'kids'::resource_kind, 'A child draws themselves doing several favorite activities to connect their body to what it can do.', 'Help a child build an early, function-focused relationship with their own body.', array['Children']::text[], '20 minutes', 'The parent and child draw the child doing a handful of favorite activities, climbing, dancing, drawing itself, and talk about what the body was doing in each picture rather than how it looked. This plants an early function-focused frame for body image before appearance-focused messages take hold more strongly. Keep the conversation light and led by what the child brings up.', '[{"id": "f0", "type": "textarea", "label": "An activity I drew myself doing"}, {"id": "f1", "type": "textarea", "label": "What my body was doing in that picture"}, {"id": "f2", "type": "textarea", "label": "Another activity I drew"}, {"id": "f3", "type": "textarea", "label": "How my body helped me do it"}, {"id": "f4", "type": "textarea", "label": "My favorite thing my body lets me do"}]'::jsonb, array['body image', 'children', 'play']::text[], '2026-09-25T15:00:00+00:00'::timestamptz)
